window.CGL_DATA=window.CGL_DATA||{};window.CGL_DATA["CGL-09-OCT-2026-SHIFT-2"]={"id":"CGL-09-OCT-2026-SHIFT-2","title":"CGL 09 OCT 2026 SHIFT 2","order":["REASONING","GK","MATH","ENGLISH"],"marking":{"correct":2,"negative":0.5},"qualifying":[],"sections":{"REASONING":{"seconds":900,"questions":[{"no":1,"local_id":"50001","quid":"Q1000071481","section":"REASONING","topic":"Miscellaneous","question":{"en":"The average weight of 10 men is increased by 2 kg when one of the men who weighs 60 kg is replaced by a new man. What is the weight of the new man? [SSC CGL 09/10/26 Shift 2]","hi":"जब 60 kg वज़न वाले एक व्यक्ति के स्थान पर एक नया व्यक्ति आता है, तो 10 व्यक्तियों का औसत वज़न 2 kg बढ़ जाता है। नए व्यक्ति का वज़न क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"70 kg"},"2":{"en":"80 kg"},"3":{"en":"48 kg"},"4":{"en":"32 kg"}},"answer":"2","solution":{"en":"Total increase = 10 × 2 = 20 kg<br>New man = 60 + 20 = 80 kg<br><br><b>Hence, the correct answer is option (2): 80 kg.</b>","hi":"कुल वृद्धि = 10 × 2 = 20 kg<br>नया व्यक्ति = 60 + 20 = 80 kg<br><br><b>अतः सही उत्तर विकल्प (2): 80 kg है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":2,"local_id":"50002","quid":"Q1000071482","section":"REASONING","topic":"Number Series","question":{"en":"What is the next number in the series?<br>2, 4, 8, 16, ? [SSC CGL 09/10/26 Shift 2]","hi":"श्रृंखला में अगली संख्या क्या है?<br>2, 4, 8, 16, ? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"20"},"2":{"en":"24"},"3":{"en":"32"},"4":{"en":"30"}},"answer":"3","solution":{"en":"Each term is multiplied by 2.<br>16 × 2 = 32<br><br><b>Hence, the correct answer is option (3): 32.</b>","hi":"प्रत्येक पद को 2 से गुणा किया जाता है।<br>16 × 2 = 32<br><br><b>अतः सही उत्तर विकल्प (3): 32 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":3,"local_id":"50003","quid":"Q1000071483","section":"REASONING","topic":"Coding & Decoding","question":{"en":"In a certain code language, \"STORM\" is written as \"UWQUO\". How will \"SWEET\" be written in the same code language? [SSC CGL 09/10/26 Shift 2]","hi":"एक निश्चित कूट भाषा में, \"STORM\" को \"UWQUO\" लिखा जाता है। उसी कूट भाषा में \"SWEET\" को कैसे लिखा जाएगा? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"VZGHU"},"2":{"en":"VZGHW"},"3":{"en":"UZGHV"},"4":{"en":"WZGHV"}},"answer":"3","solution":{"en":"STORM → UWQUO: +2, +3, +2, +3, +2<br>SWEET: S+2 = U, W+3 = Z, E+2 = G, E+3 = H, T+2 = V<br>Code = UZGHV<br><br><b>Hence, the correct answer is option (3): UZGHV.</b>","hi":"STORM → UWQUO: +2, +3, +2, +3, +2<br>SWEET: S+2 = U, W+3 = Z, E+2 = G, E+3 = H, T+2 = V<br>कूट = UZGHV<br><br><b>अतः सही उत्तर विकल्प (3): UZGHV है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":4,"local_id":"50004","quid":"Q1000071484","section":"REASONING","topic":"Miscellaneous","question":{"en":"The ratio of incomes of P and Q is 7 : 9, and the ratio of their expenditures is 5 : 7. If each saves ₹6,000, what is P’s income? [SSC CGL 09/10/26 Shift 2]","hi":"P और Q की आय का अनुपात 7 : 9 है, और उनके व्यय का अनुपात 5 : 7 है। यदि प्रत्येक ₹6,000 बचाता है, तो P की आय क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"₹21,000"},"2":{"en":"₹28,000"},"3":{"en":"₹35,000"},"4":{"en":"₹42,000"}},"answer":"1","solution":{"en":"Let incomes be 7x, 9x and expenditures 5y, 7y.<br>7x − 5y = 9x − 7y ⇒ x = y<br>7x − 5x = 6000 ⇒ x = 3000<br>P’s income = 7 × 3000 = ₹21,000<br><br><b>Hence, the correct answer is option (1): ₹21,000.</b>","hi":"माना आय 7x, 9x और व्यय 5y, 7y है।<br>7x − 5y = 9x − 7y ⇒ x = y<br>7x − 5x = 6000 ⇒ x = 3000<br>P की आय = 7 × 3000 = ₹21,000<br><br><b>अतः सही उत्तर विकल्प (1): ₹21,000 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":5,"local_id":"50005","quid":"Q1000071485","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"Choose the option that perfectly matches the given address.<br><br>Original Address:<br>Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII-BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America [SSC CGL 09/10/26 Shift 2]","hi":"वह विकल्प चुनिए जो दिए गए पते से पूरी तरह मेल खाता है।<br><br>मूल पता:<br>Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII-BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Residence Unit β-44/ΩKings Residence Royale. Phase-VII-BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America"},"2":{"en":"Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America"},"3":{"en":"Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII-BSt. Patricks Crescent-WestSan Francisco, California 94107United States of America | North America"},"4":{"en":"Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII-BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America"}},"answer":"4","solution":{"en":"(A) has \"Kings\" and \"Royale.\"; (B) misses the hyphen in \"VII-B\"; (C) has \"Patricks\".<br>Only (D) matches exactly.<br><br><b>Hence, the correct answer is option (4): Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII-BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America.</b>","hi":"(A) में \"Kings\" और \"Royale.\" है; (B) में \"VII-B\" का हाइफ़न नहीं है; (C) में \"Patricks\" है।<br>केवल (D) पूरी तरह मेल खाता है।<br><br><b>अतः सही उत्तर विकल्प (4): Residence Unit β-44/ΩKing’s Residence Royale, Phase-VII-BSt. Patrick’s Crescent-WestSan Francisco, California 94107United States of America | North America है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":6,"local_id":"50006","quid":"Q1000071486","section":"REASONING","topic":"Missing Number","question":{"en":"In the following question, a matrix of numbers is given. These numbers follow a certain pattern either row-wise or column-wise. Identify this pattern and choose the missing number accordingly.<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">1</td><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">3</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">6</td><td style=\"border:1px solid #888;padding:3px 6px\">7</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">24</td><td style=\"border:1px solid #888;padding:3px 6px\">32</td><td style=\"border:1px solid #888;padding:3px 6px\">?</td></tr></table> [SSC CGL 09/10/26 Shift 2]","hi":"निम्नलिखित प्रश्न में संख्याओं का एक आव्यूह दिया गया है। ये संख्याएँ पंक्ति-वार या स्तंभ-वार एक निश्चित पैटर्न का अनुसरण करती हैं। इस पैटर्न को पहचानिए और तदनुसार लुप्त संख्या चुनिए।<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">1</td><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">3</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">6</td><td style=\"border:1px solid #888;padding:3px 6px\">7</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">24</td><td style=\"border:1px solid #888;padding:3px 6px\">32</td><td style=\"border:1px solid #888;padding:3px 6px\">?</td></tr></table> [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"34"},"2":{"en":"38"},"3":{"en":"40"},"4":{"en":"46"}},"answer":"3","solution":{"en":"Column-wise: (first + second) × 4 = third<br>(1 + 5) × 4 = 24, (2 + 6) × 4 = 32<br>(3 + 7) × 4 = 40<br><br><b>Hence, the correct answer is option (3): 40.</b>","hi":"स्तंभ-वार: (पहली + दूसरी) × 4 = तीसरी<br>(1 + 5) × 4 = 24, (2 + 6) × 4 = 32<br>(3 + 7) × 4 = 40<br><br><b>अतः सही उत्तर विकल्प (3): 40 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":7,"local_id":"50007","quid":"Q1000071487","section":"REASONING","topic":"Blood Relations","question":{"en":"P and Q are siblings, with P being male. R is the mother of Q. S is the father of R, while T is the mother of S. Based on the information provided, what is the relationship of P with T? [SSC CGL 09/10/26 Shift 2]","hi":"P और Q भाई-बहन हैं, जिनमें P पुरुष है। R, Q की माता है। S, R का पिता है, जबकि T, S की माता है। दी गई जानकारी के आधार पर, P का T से क्या संबंध है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Grandson","hi":"पोता"},"2":{"en":"Granddaughter","hi":"पोती"},"3":{"en":"Great-grandson","hi":"परपोता"},"4":{"en":"Great-granddaughter","hi":"परपोती"}},"answer":"3","solution":{"en":"<svg width=\"260\" height=\"220\" viewBox=\"0 0 260 220\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M82 186H142M110 31V64M110 64V68M110 86V119M110 119V123M110 141V174M70 174H150M70 174V178M150 174V178\"/><g fill=\"#000\" stroke=\"none\" text-anchor=\"middle\"><text x=\"110\" y=\"25\" font-weight=\"bold\">T−</text><text x=\"110\" y=\"80\">S+</text><text x=\"110\" y=\"135\">R−</text><text x=\"70\" y=\"190\" font-weight=\"bold\">P+</text><text x=\"150\" y=\"190\">Q</text></g><text x=\"4\" y=\"216\" fill=\"#555\" stroke=\"none\" font-size=\"10\">+ Male  − Female  — Sibling  = Couple  | Generation</text></svg><br>T → S (son) → R (daughter) → P (male).<br>P is three generations below T, so P is T's Great-grandson.<br><br><b>Hence, the correct answer is option (3): Great-grandson.</b>","hi":"<svg width=\"260\" height=\"220\" viewBox=\"0 0 260 220\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M82 186H142M110 31V64M110 64V68M110 86V119M110 119V123M110 141V174M70 174H150M70 174V178M150 174V178\"/><g fill=\"#000\" stroke=\"none\" text-anchor=\"middle\"><text x=\"110\" y=\"25\" font-weight=\"bold\">T−</text><text x=\"110\" y=\"80\">S+</text><text x=\"110\" y=\"135\">R−</text><text x=\"70\" y=\"190\" font-weight=\"bold\">P+</text><text x=\"150\" y=\"190\">Q</text></g><text x=\"4\" y=\"216\" fill=\"#555\" stroke=\"none\" font-size=\"10\">+ पुरुष  − स्त्री  — भाई-बहन  = पति-पत्नी  | पीढ़ी</text></svg><br>T → S (पुत्र) → R (पुत्री) → P (पुरुष)।<br>P, T से तीन पीढ़ी नीचे है, अतः P, T का परपोता है।<br><br><b>अतः सही उत्तर विकल्प (3): परपोता है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":8,"local_id":"50008","quid":"Q1000071488","section":"REASONING","topic":"Miscellaneous","question":{"en":"Centre codes are generated such that the first digit is the cube root of the last three digits. Which centre code is invalid? [SSC CGL 09/10/26 Shift 2]","hi":"केंद्र कोड इस प्रकार बनाए जाते हैं कि पहला अंक अंतिम तीन अंकों का घनमूल होता है। कौन-सा केंद्र कोड अमान्य है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"3027"},"2":{"en":"4064"},"3":{"en":"6216"},"4":{"en":"7350"}},"answer":"4","solution":{"en":"3³ = 027, 4³ = 064, 6³ = 216 ✓<br>7³ = 343, not 350, so 7350 is invalid.<br><br><b>Hence, the correct answer is option (4): 7350.</b>","hi":"3³ = 027, 4³ = 064, 6³ = 216 ✓<br>7³ = 343 है, 350 नहीं, अतः 7350 अमान्य है।<br><br><b>अतः सही उत्तर विकल्प (4): 7350 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":9,"local_id":"50009","quid":"Q1000071489","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"<b>Choose the option which is exactly similar to:</b> 24th September 2024, House No-45, Chandni Chowk, New Delhi-110006 [SSC CGL 09/10/26 Shift 2]","hi":"<b>वह विकल्प चुनिए जो इसके बिल्कुल समान है:</b> 24th September 2024, House No-45, Chandni Chowk, New Delhi-110006 [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"24th September 2024, House No.-45, Chandni Chowk, New Delhi-110006"},"2":{"en":"25th September 2024, House No-45, Chandni Chowk, New Delhi-110006"},"3":{"en":"24th September 2024, House No-45, Chandni Chowk, New Delhi-110006"},"4":{"en":"24th September 2024, House No-45, Chandni Chowk, New Delhi-110001"}},"answer":"3","solution":{"en":"(A) has \"No.-45\", (B) has \"25th\", (D) has \"110001\".<br>Only (C) is exactly the same.<br><br><b>Hence, the correct answer is option (3): 24th September 2024, House No-45, Chandni Chowk, New Delhi-110006.</b>","hi":"(A) में \"No.-45\", (B) में \"25th\", (D) में \"110001\" है।<br>केवल (C) बिल्कुल समान है।<br><br><b>अतः सही उत्तर विकल्प (3): 24th September 2024, House No-45, Chandni Chowk, New Delhi-110006 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":10,"local_id":"50010","quid":"Q1000071490","section":"REASONING","topic":"Situational Judgement","question":{"en":"During a group activity, a participant with a speech impediment is mocked by another team member, causing the affected individual to withdraw and remain silent. Which of the following actions represents the most professional and supportive response to this situation? [SSC CGL 09/10/26 Shift 2]","hi":"एक समूह गतिविधि के दौरान, वाणी दोष वाले एक प्रतिभागी का किसी अन्य टीम सदस्य द्वारा मज़ाक उड़ाया जाता है, जिससे प्रभावित व्यक्ति पीछे हट जाता है और चुप रहता है। निम्नलिखित में से कौन-सी कार्रवाई इस स्थिति के प्रति सबसे पेशेवर और सहायक प्रतिक्रिया है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Offer an immediate apology to the group on their behalf to avoid any social awkwardness.","hi":"किसी भी सामाजिक असहजता से बचने के लिए उनकी ओर से समूह से तुरंत माफ़ी माँगना।"},"2":{"en":"Choose to completely ignore the entire situation to avoid escalating tension in the group.","hi":"समूह में तनाव बढ़ने से बचाने के लिए पूरी स्थिति को पूरी तरह अनदेखा करना।"},"3":{"en":"Address the behaviour immediately, clarify that it is unacceptable, and ensure support exists.","hi":"उस व्यवहार पर तुरंत ध्यान देना, स्पष्ट करना कि यह अस्वीकार्य है, और सहायता सुनिश्चित करना।"},"4":{"en":"Ask the affected participant to step out of the room so they can take a necessary break.","hi":"प्रभावित प्रतिभागी को कमरे से बाहर जाने को कहना ताकि वे आवश्यक विराम ले सकें।"}},"answer":"3","solution":{"en":"Mocking must be stopped at once and the affected person supported.<br>Ignoring it, apologising for the victim or sending them out does not solve the problem.<br><br><b>Hence, the correct answer is option (3): Address the behaviour immediately, clarify that it is unacceptable, and ensure support exists..</b>","hi":"मज़ाक उड़ाना तुरंत रोकना चाहिए और प्रभावित व्यक्ति की सहायता करनी चाहिए।<br>अनदेखा करना, पीड़ित की ओर से माफ़ी माँगना या उसे बाहर भेजना समस्या हल नहीं करता।<br><br><b>अतः सही उत्तर विकल्प (3): उस व्यवहार पर तुरंत ध्यान देना, स्पष्ट करना कि यह अस्वीकार्य है, और सहायता सुनिश्चित करना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":11,"local_id":"50011","quid":"Q1000071491","section":"REASONING","topic":"Situational Judgement","question":{"en":"You're leading a team where one member is frequently missing deadlines. Instead of improving, they start avoiding communication. The rest of the team is frustrated. What is the most effective action? [SSC CGL 09/10/26 Shift 2]","hi":"आप एक टीम का नेतृत्व कर रहे हैं जिसमें एक सदस्य बार-बार समय-सीमाएँ चूक रहा है। सुधार करने के बजाय, वह संवाद से बचने लगता है। टीम के बाकी सदस्य निराश हैं। सबसे प्रभावी कार्रवाई क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Immediately issue a formal written warning to both employees stating that any further displays of hostility will lead to immediate termination from their respective roles within the company.","hi":"दोनों कर्मचारियों को तुरंत एक औपचारिक लिखित चेतावनी जारी करना कि शत्रुता के किसी भी और प्रदर्शन पर उन्हें कंपनी में उनकी संबंधित भूमिकाओं से तुरंत हटा दिया जाएगा।"},"2":{"en":"Publicly address the conflict during the next team meeting to highlight the unprofessional nature of their behavior and inform the rest of the team that this conduct will no longer be tolerated.","hi":"अगली टीम बैठक में सार्वजनिक रूप से संघर्ष पर बात करना ताकि उनके व्यवहार की अव्यावसायिक प्रकृति उजागर हो और बाकी टीम को बताना कि यह आचरण अब सहन नहीं किया जाएगा।"},"3":{"en":"Choose to ignore their personal conflict entirely, assuming that they are mature enough to manage their own behavior and that the situation will resolve itself naturally as the project progresses.","hi":"उनके निजी संघर्ष को पूरी तरह अनदेखा करना, यह मानते हुए कि वे अपने व्यवहार को संभालने के लिए पर्याप्त परिपक्व हैं और परियोजना आगे बढ़ने के साथ स्थिति अपने आप सुलझ जाएगी।"},"4":{"en":"Schedule separate, private meetings with each employee to hear their perspectives, and then facilitate a joint mediation session to resolve their underlying conflicts and establish new ground rules.","hi":"प्रत्येक कर्मचारी के साथ अलग, निजी बैठकें निर्धारित करके उनके दृष्टिकोण सुनना, और फिर उनके मूल संघर्षों को सुलझाने तथा नए बुनियादी नियम तय करने के लिए एक संयुक्त मध्यस्थता सत्र आयोजित करना।"}},"answer":"4","solution":{"en":"Private conversations first help to understand the causes without embarrassing anyone.<br>A joint session with clear ground rules then resolves the issue for the whole team.<br><br><b>Hence, the correct answer is option (4): Schedule separate, private meetings with each employee to hear their perspectives, and then facilitate a joint mediation session to resolve their underlying conflicts and establish new ground rules..</b>","hi":"पहले निजी बातचीत से किसी को शर्मिंदा किए बिना कारण समझ आते हैं।<br>फिर स्पष्ट नियमों के साथ संयुक्त सत्र पूरी टीम के लिए समस्या हल करता है।<br><br><b>अतः सही उत्तर विकल्प (4): प्रत्येक कर्मचारी के साथ अलग, निजी बैठकें निर्धारित करके उनके दृष्टिकोण सुनना, और फिर उनके मूल संघर्षों को सुलझाने तथा नए बुनियादी नियम तय करने के लिए एक संयुक्त मध्यस्थता सत्र आयोजित करना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":12,"local_id":"50012","quid":"Q1000071492","section":"REASONING","topic":"Letter/Alphabetical Analogy","question":{"en":"What should come in place of the question mark (?) in the following analogy?<br>BEH : KNQ :: TWZ : ? [SSC CGL 09/10/26 Shift 2]","hi":"निम्नलिखित सादृश्य में प्रश्न चिह्न (?) के स्थान पर क्या आना चाहिए?<br>BEH : KNQ :: TWZ : ? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"BFI"},"2":{"en":"CEI"},"3":{"en":"CFI"},"4":{"en":"CFH"}},"answer":"3","solution":{"en":"BEH → KNQ: each letter +9<br>TWZ: T+9 = C, W+9 = F, Z+9 = I → CFI<br><br><b>Hence, the correct answer is option (3): CFI.</b>","hi":"BEH → KNQ: प्रत्येक अक्षर +9<br>TWZ: T+9 = C, W+9 = F, Z+9 = I → CFI<br><br><b>अतः सही उत्तर विकल्प (3): CFI है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":13,"local_id":"50013","quid":"Q1000071493","section":"REASONING","topic":"Syllogism","question":{"en":"In the given question, a few statements have been given followed by conclusions based on them. Consider the statements to be true and answer which of the given conclusions logically follow the statement.<br><br>Statements<br>1. No scientist is careless.<br>2. All researchers are scientists.<br>3. Some professors are researchers.<br><br>Conclusions<br>I. No researcher is careless.<br>II. Some professors are not careless.<br>III. All scientists are researchers.<br>IV. Some professors are scientists. [SSC CGL 09/10/26 Shift 2]","hi":"दिए गए प्रश्न में कुछ कथन और उन पर आधारित निष्कर्ष दिए गए हैं। कथनों को सत्य मानते हुए बताइए कि दिए गए निष्कर्षों में से कौन-से तार्किक रूप से कथन का अनुसरण करते हैं।<br><br>कथन<br>1. कोई भी वैज्ञानिक लापरवाह नहीं है।<br>2. सभी शोधकर्ता वैज्ञानिक हैं।<br>3. कुछ प्रोफ़ेसर शोधकर्ता हैं।<br><br>निष्कर्ष<br>I. कोई भी शोधकर्ता लापरवाह नहीं है।<br>II. कुछ प्रोफ़ेसर लापरवाह नहीं हैं।<br>III. सभी वैज्ञानिक शोधकर्ता हैं।<br>IV. कुछ प्रोफ़ेसर वैज्ञानिक हैं। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Only I, II and IV follow","hi":"केवल I, II और IV अनुसरण करते हैं"},"2":{"en":"Only I and II follow","hi":"केवल I और II अनुसरण करते हैं"},"3":{"en":"Only II, III and IV follow","hi":"केवल II, III और IV अनुसरण करते हैं"},"4":{"en":"All four follow","hi":"चारों अनुसरण करते हैं"}},"answer":"1","solution":{"en":"Researchers ⊂ Scientists, and no scientist is careless → I follows.<br>Some professors are researchers, hence scientists → IV follows; they are not careless → II follows.<br>All researchers are scientists does not mean all scientists are researchers → III does not follow.<br><br><b>Hence, the correct answer is option (1): Only I, II and IV follow.</b>","hi":"शोधकर्ता ⊂ वैज्ञानिक, और कोई वैज्ञानिक लापरवाह नहीं → I अनुसरण करता है।<br>कुछ प्रोफ़ेसर शोधकर्ता, अतः वैज्ञानिक हैं → IV; वे लापरवाह नहीं → II अनुसरण करता है।<br>सभी शोधकर्ता वैज्ञानिक हैं का अर्थ यह नहीं कि सभी वैज्ञानिक शोधकर्ता हैं → III नहीं।<br><br><b>अतः सही उत्तर विकल्प (1): केवल I, II और IV अनुसरण करते हैं है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":14,"local_id":"50014","quid":"Q1000071494","section":"REASONING","topic":"Statement & Conclusion","question":{"en":"In the following question, one statement is given, followed by certain inferences. Consider the statement to be true even if it seems to contradict commonly known facts. Read the inferences carefully and decide which of them logically follow from the given statement.<br><b>Statement:</b><br>To enhance employee skills, the company has started organising regular training sessions and professional development workshops.<br><b>Inferences:</b><br>I. The company considers skill development beneficial for employees.<br>II. None of the employees possesses the required skills.<br>III. Training programs may help improve employee performance. [SSC CGL 09/10/26 Shift 2]","hi":"निम्नलिखित प्रश्न में एक कथन और उसके बाद कुछ अनुमान दिए गए हैं। कथन को सत्य मानिए, भले ही वह सामान्य रूप से ज्ञात तथ्यों से भिन्न प्रतीत हो। अनुमानों को ध्यान से पढ़िए और तय कीजिए कि उनमें से कौन-से दिए गए कथन का तार्किक रूप से अनुसरण करते हैं।<br><b>कथन:</b><br>कर्मचारियों के कौशल को बढ़ाने के लिए, कंपनी ने नियमित प्रशिक्षण सत्र और व्यावसायिक विकास कार्यशालाएँ आयोजित करना शुरू किया है।<br><b>अनुमान:</b><br>I. कंपनी कौशल विकास को कर्मचारियों के लिए लाभदायक मानती है।<br>II. किसी भी कर्मचारी के पास आवश्यक कौशल नहीं है।<br>III. प्रशिक्षण कार्यक्रम कर्मचारियों के प्रदर्शन को सुधारने में मदद कर सकते हैं। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Only inferences I and II follow.","hi":"केवल अनुमान I और II अनुसरण करते हैं।"},"2":{"en":"Only inferences II and III follow.","hi":"केवल अनुमान II और III अनुसरण करते हैं।"},"3":{"en":"Only inferences I and III follow.","hi":"केवल अनुमान I और III अनुसरण करते हैं।"},"4":{"en":"All inferences follow.","hi":"सभी अनुमान अनुसरण करते हैं।"}},"answer":"3","solution":{"en":"Training is started to enhance skills, so the company finds it beneficial (I) and expects better performance (III).<br>II is extreme; enhancing skills does not mean no one has them.<br><br><b>Hence, the correct answer is option (3): Only inferences I and III follow..</b>","hi":"कौशल बढ़ाने के लिए प्रशिक्षण शुरू किया गया, अतः कंपनी इसे लाभदायक मानती है (I) और बेहतर प्रदर्शन की आशा करती है (III)।<br>II अतिवादी है; कौशल बढ़ाने का अर्थ यह नहीं कि किसी के पास कौशल नहीं।<br><br><b>अतः सही उत्तर विकल्प (3): केवल अनुमान I और III अनुसरण करते हैं। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":15,"local_id":"50015","quid":"Q1000071495","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"Among the four given combinations, two are exactly identical. Identify the matching pair.<br><br>1. Mohd. Arif Khan, Bldg-25, Flat 4103, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010<br>2. Mohd Arif Khan, Bldg-25, Flat 4103, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010<br>3. Mohd. Arif Khan, Bldg-25, Flat 4103, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010<br>4. Mohd. Arif Khan, Bldg-25, Flat 4130, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010 [SSC CGL 09/10/26 Shift 2]","hi":"दिए गए चार संयोजनों में से दो बिल्कुल समान हैं। मेल खाने वाला युग्म पहचानिए।<br><br>1. Mohd. Arif Khan, Bldg-25, Flat 4103, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010<br>2. Mohd Arif Khan, Bldg-25, Flat 4103, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010<br>3. Mohd. Arif Khan, Bldg-25, Flat 4103, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010<br>4. Mohd. Arif Khan, Bldg-25, Flat 4130, Sapphire Towers, 6<sup>th</sup> main road, Lucknow – 226010 [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"1 &amp; 2"},"2":{"en":"2 &amp; 3"},"3":{"en":"1 &amp; 3"},"4":{"en":"3 &amp; 4"}},"answer":"3","solution":{"en":"2 has \"Mohd\" without the full stop; 4 has \"Flat 4130\".<br>1 and 3 are exactly identical.<br><br><b>Hence, the correct answer is option (3): 1 &amp; 3.</b>","hi":"2 में \"Mohd\" के बाद पूर्ण विराम नहीं है; 4 में \"Flat 4130\" है।<br>1 और 3 बिल्कुल समान हैं।<br><br><b>अतः सही उत्तर विकल्प (3): 1 &amp; 3 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":16,"local_id":"50016","quid":"Q1000071496","section":"REASONING","topic":"Situational Judgement","question":{"en":"A senior leader is about to announce a major organizational restructuring that will lead to layoffs and role changes, causing significant anxiety among employees.<br><br>Which approach by the leader best demonstrates high emotional intelligence (EI)? [SSC CGL 09/10/26 Shift 2]","hi":"एक वरिष्ठ नेता एक बड़े संगठनात्मक पुनर्गठन की घोषणा करने वाले हैं जिससे छँटनी और भूमिकाओं में बदलाव होंगे, और कर्मचारियों में काफ़ी चिंता है।<br><br>नेता का कौन-सा दृष्टिकोण उच्च भावनात्मक बुद्धिमत्ता (EI) को सबसे अच्छी तरह दर्शाता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Send a cold corporate email broadcast to shield themselves from staff shock and emotional reactions.","hi":"कर्मचारियों के सदमे और भावनात्मक प्रतिक्रियाओं से स्वयं को बचाने के लिए एक रूखा कॉर्पोरेट ईमेल भेजना।"},"2":{"en":"Highlight only financial growth projections while completely ignoring job security concerns and staff anxiety.","hi":"नौकरी की सुरक्षा की चिंताओं और कर्मचारियों की व्यग्रता को पूरी तरह अनदेखा करते हुए केवल वित्तीय वृद्धि के अनुमानों पर ज़ोर देना।"},"3":{"en":"Withhold the restructuring information entirely until the morning it takes effect to protect daily productivity.","hi":"दैनिक उत्पादकता की रक्षा के लिए पुनर्गठन की जानकारी उसके लागू होने की सुबह तक पूरी तरह छिपाए रखना।"},"4":{"en":"Conduct a live, transparent briefing that validates staff anxiety, addresses challenges, and explains strategic necessity.","hi":"एक प्रत्यक्ष, पारदर्शी ब्रीफ़िंग करना जो कर्मचारियों की चिंता को स्वीकार करे, चुनौतियों पर बात करे और रणनीतिक आवश्यकता समझाए।"}},"answer":"4","solution":{"en":"High EI means recognising others' emotions and communicating openly.<br>A live, transparent briefing that acknowledges anxiety does exactly this.<br><br><b>Hence, the correct answer is option (4): Conduct a live, transparent briefing that validates staff anxiety, addresses challenges, and explains strategic necessity..</b>","hi":"उच्च EI का अर्थ है दूसरों की भावनाओं को पहचानना और खुलकर संवाद करना।<br>चिंता को स्वीकार करने वाली प्रत्यक्ष, पारदर्शी ब्रीफ़िंग यही करती है।<br><br><b>अतः सही उत्तर विकल्प (4): एक प्रत्यक्ष, पारदर्शी ब्रीफ़िंग करना जो कर्मचारियों की चिंता को स्वीकार करे, चुनौतियों पर बात करे और रणनीतिक आवश्यकता समझाए। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":17,"local_id":"50017","quid":"Q1000071497","section":"REASONING","topic":"Eligibility","question":{"en":"<b>Read the given conditions carefully and determine the appropriate outcome for the case provided. If any exception applies, identify the authority to whom the case should be referred.</b><br><b>Criteria for Professional Medical Fellowship:</b><br>(i) Must hold an MBBS degree.<br>(ii) Must have completed a 2-year internship.<br><b>Exceptions:</b><br><b>Exception (A):</b> If the internship is only 1 year but the candidate holds a Master's in Surgery, refer the case to the Medical Board.<br><b>Exception (B):</b> If the candidate meets both criteria (i) and (ii) but has a gap in medical practice exceeding 3 years, refer the case to the Ethics Committee.<br><b>Case:</b> The candidate has an MBBS, a 1-year internship, and a Master's in Surgery. [SSC CGL 09/10/26 Shift 2]","hi":"<b>दी गई शर्तों को ध्यान से पढ़िए और दिए गए मामले के लिए उपयुक्त परिणाम निर्धारित कीजिए। यदि कोई अपवाद लागू होता है, तो उस प्राधिकारी की पहचान कीजिए जिसे मामला भेजा जाना चाहिए।</b><br><b>व्यावसायिक चिकित्सा फ़ेलोशिप के मानदंड:</b><br>(i) MBBS डिग्री होनी चाहिए।<br>(ii) 2 वर्ष की इंटर्नशिप पूरी की होनी चाहिए।<br><b>अपवाद:</b><br><b>अपवाद (A):</b> यदि इंटर्नशिप केवल 1 वर्ष की है लेकिन उम्मीदवार के पास सर्जरी में मास्टर डिग्री है, तो मामला मेडिकल बोर्ड को भेजें।<br><b>अपवाद (B):</b> यदि उम्मीदवार मानदंड (i) और (ii) दोनों पूरे करता है लेकिन चिकित्सा अभ्यास में 3 वर्ष से अधिक का अंतराल है, तो मामला नैतिकता समिति को भेजें।<br><b>मामला:</b> उम्मीदवार के पास MBBS, 1 वर्ष की इंटर्नशिप और सर्जरी में मास्टर डिग्री है। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Fellowship to be approved","hi":"फ़ेलोशिप स्वीकृत की जाए"},"2":{"en":"Case to be referred to the Medical Board","hi":"मामला मेडिकल बोर्ड को भेजा जाए"},"3":{"en":"Application to be rejected","hi":"आवेदन अस्वीकार किया जाए"},"4":{"en":"Case to be referred to the Ethics Committee","hi":"मामला नैतिकता समिति को भेजा जाए"}},"answer":"2","solution":{"en":"The internship is only 1 year, so criterion (ii) fails.<br>But the candidate has a Master's in Surgery, so Exception (A) applies → refer to the Medical Board.<br><br><b>Hence, the correct answer is option (2): Case to be referred to the Medical Board.</b>","hi":"इंटर्नशिप केवल 1 वर्ष की है, अतः मानदंड (ii) पूरा नहीं होता।<br>पर उम्मीदवार के पास सर्जरी में मास्टर डिग्री है, अतः अपवाद (A) लागू → मेडिकल बोर्ड को भेजें।<br><br><b>अतः सही उत्तर विकल्प (2): मामला मेडिकल बोर्ड को भेजा जाए है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":18,"local_id":"50018","quid":"Q1000071498","section":"REASONING","topic":"Statement & Conclusion","question":{"en":"Read the statement carefully and assume it to be true. Then examine the two conclusions given below it and decide which conclusion(s), if any, logically follow from the statement.<br><b>Statement:</b><br>A state education board has introduced competency-based evaluation alongside existing examination patterns to improve assessment quality.<br><b>Conclusions:</b><br>I. Traditional examinations have been completely abolished.<br>II. Competency-based evaluation guarantees perfect academic scoring accuracy. [SSC CGL 09/10/26 Shift 2]","hi":"कथन को ध्यान से पढ़िए और उसे सत्य मानिए। फिर उसके नीचे दिए गए दो निष्कर्षों की जाँच कीजिए और तय कीजिए कि कौन-सा/से निष्कर्ष, यदि कोई हो, कथन का तार्किक रूप से अनुसरण करता/करते है/हैं।<br><b>कथन:</b><br>एक राज्य शिक्षा बोर्ड ने मूल्यांकन की गुणवत्ता सुधारने के लिए मौजूदा परीक्षा पैटर्न के साथ-साथ योग्यता-आधारित मूल्यांकन शुरू किया है।<br><b>निष्कर्ष:</b><br>I. पारंपरिक परीक्षाएँ पूरी तरह समाप्त कर दी गई हैं।<br>II. योग्यता-आधारित मूल्यांकन पूर्ण शैक्षणिक अंकन सटीकता की गारंटी देता है। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Only conclusion I follows","hi":"केवल निष्कर्ष I अनुसरण करता है"},"2":{"en":"Only conclusion II follows","hi":"केवल निष्कर्ष II अनुसरण करता है"},"3":{"en":"Both conclusions I and II follow","hi":"निष्कर्ष I और II दोनों अनुसरण करते हैं"},"4":{"en":"Neither conclusion I nor conclusion II follows","hi":"न तो निष्कर्ष I और न ही निष्कर्ष II अनुसरण करता है"}},"answer":"4","solution":{"en":"The new method is added \"alongside\" existing exams, so I is false.<br>\"Improve quality\" does not mean \"guarantees perfect accuracy\", so II does not follow.<br><br><b>Hence, the correct answer is option (4): Neither conclusion I nor conclusion II follows.</b>","hi":"नई पद्धति मौजूदा परीक्षाओं के \"साथ-साथ\" जोड़ी गई है, अतः I गलत है।<br>\"गुणवत्ता सुधारना\" का अर्थ \"पूर्ण सटीकता की गारंटी\" नहीं है, अतः II नहीं।<br><br><b>अतः सही उत्तर विकल्प (4): न तो निष्कर्ष I और न ही निष्कर्ष II अनुसरण करता है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":19,"local_id":"50019","quid":"Q1000071499","section":"REASONING","topic":"Coding & Decoding","question":{"en":"In a certain code language, \"HOUSE\" is written as \"iOvSf\". How will \"PLANE\" be written in the same code language? [SSC CGL 09/10/26 Shift 2]","hi":"एक निश्चित कूट भाषा में, \"HOUSE\" को \"iOvSf\" लिखा जाता है। उसी कूट भाषा में \"PLANE\" को कैसे लिखा जाएगा? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"qLbNf"},"2":{"en":"pLbNf"},"3":{"en":"qLcNf"},"4":{"en":"qLbMf"}},"answer":"1","solution":{"en":"Letters at positions 1, 3, 5 move +1 and become small; positions 2, 4 stay the same.<br>PLANE: P → q, L, A → b, N, E → f → qLbNf<br><br><b>Hence, the correct answer is option (1): qLbNf.</b>","hi":"स्थान 1, 3, 5 के अक्षर +1 होकर छोटे हो जाते हैं; स्थान 2, 4 वही रहते हैं।<br>PLANE: P → q, L, A → b, N, E → f → qLbNf<br><br><b>अतः सही उत्तर विकल्प (1): qLbNf है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":20,"local_id":"50020","quid":"Q1000071500","section":"REASONING","topic":"Coding & Decoding","question":{"en":"In a certain code language, \"STREET\" is written as \"SuRfEu\". How will \"FLIGHT\" be written in the same code language? [SSC CGL 09/10/26 Shift 2]","hi":"एक निश्चित कूट भाषा में, \"STREET\" को \"SuRfEu\" लिखा जाता है। उसी कूट भाषा में \"FLIGHT\" को कैसे लिखा जाएगा? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"FmIgHu"},"2":{"en":"FnIhHu"},"3":{"en":"FmIhTu"},"4":{"en":"FmIhHu"}},"answer":"4","solution":{"en":"Letters at odd positions stay the same; letters at even positions move +1 and become small.<br>FLIGHT: F, L → m, I, G → h, H, T → u → FmIhHu<br><br><b>Hence, the correct answer is option (4): FmIhHu.</b>","hi":"विषम स्थानों के अक्षर वही रहते हैं; सम स्थानों के अक्षर +1 होकर छोटे हो जाते हैं।<br>FLIGHT: F, L → m, I, G → h, H, T → u → FmIhHu<br><br><b>अतः सही उत्तर विकल्प (4): FmIhHu है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":21,"local_id":"50021","quid":"Q1000071501","section":"REASONING","topic":"Statement, Assumption & Argument","question":{"en":"A public sector organization recently implemented a software system that reduced processing errors by 30%. However, employees report that the system occasionally produces inaccurate outputs under rare conditions. Management decides to continue using the system without modification, arguing that the 30% reduction in overall errors outweighs the risk of rare inaccuracies.<br><br>Which of the following, if true, most seriously weakens management's argument? [SSC CGL 09/10/26 Shift 2]","hi":"एक सार्वजनिक क्षेत्र के संगठन ने हाल ही में एक सॉफ़्टवेयर प्रणाली लागू की जिससे प्रसंस्करण त्रुटियाँ 30% कम हो गईं। हालाँकि, कर्मचारी बताते हैं कि यह प्रणाली दुर्लभ परिस्थितियों में कभी-कभी गलत परिणाम देती है। प्रबंधन बिना किसी संशोधन के प्रणाली का उपयोग जारी रखने का निर्णय लेता है, यह तर्क देते हुए कि कुल त्रुटियों में 30% की कमी दुर्लभ अशुद्धियों के जोखिम से अधिक महत्वपूर्ण है।<br><br>निम्नलिखित में से कौन-सा, यदि सत्य हो, प्रबंधन के तर्क को सबसे अधिक कमज़ोर करता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"The manual errors previously made by employees were easier to detect and fix than the system's inaccurate outputs.","hi":"कर्मचारियों द्वारा पहले की गई मैन्युअल त्रुटियाँ प्रणाली के गलत परिणामों की तुलना में पहचानने और सुधारने में आसान थीं।"},"2":{"en":"Employees require additional training to fully understand all the features of the new software system.","hi":"नई सॉफ़्टवेयर प्रणाली की सभी विशेषताओं को पूरी तरह समझने के लिए कर्मचारियों को अतिरिक्त प्रशिक्षण की आवश्यकता है।"},"3":{"en":"The software system cost less to implement than the projected annual losses caused by manual errors.","hi":"सॉफ़्टवेयर प्रणाली को लागू करने की लागत मैन्युअल त्रुटियों से होने वाले अनुमानित वार्षिक नुकसान से कम थी।"},"4":{"en":"Other public sector organizations using similar software have reported a 35% reduction in processing errors.","hi":"समान सॉफ़्टवेयर का उपयोग करने वाले अन्य सार्वजनिक क्षेत्र के संगठनों ने प्रसंस्करण त्रुटियों में 35% की कमी बताई है।"}},"answer":"1","solution":{"en":"The argument compares only the number of errors.<br>If the system's errors are harder to detect and fix, a few of them can be more harmful than many manual errors, so (A) weakens it most.<br><br><b>Hence, the correct answer is option (1): The manual errors previously made by employees were easier to detect and fix than the system's inaccurate outputs..</b>","hi":"तर्क केवल त्रुटियों की संख्या की तुलना करता है।<br>यदि प्रणाली की त्रुटियाँ पहचानने और सुधारने में कठिन हैं, तो थोड़ी त्रुटियाँ भी अधिक हानिकारक हो सकती हैं, अतः (A) सबसे अधिक कमज़ोर करता है।<br><br><b>अतः सही उत्तर विकल्प (1): कर्मचारियों द्वारा पहले की गई मैन्युअल त्रुटियाँ प्रणाली के गलत परिणामों की तुलना में पहचानने और सुधारने में आसान थीं। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":22,"local_id":"50022","quid":"Q1000071502","section":"REASONING","topic":"Letter & Alphanumeric Series","question":{"en":"Study the pattern in the given series and find the next set of letters in the series.<br>HOM, ESJ, BWG, YAD, ? [SSC CGL 09/10/26 Shift 2]","hi":"दी गई श्रृंखला के पैटर्न का अध्ययन कीजिए और श्रृंखला में अक्षरों का अगला समूह ज्ञात कीजिए।<br>HOM, ESJ, BWG, YAD, ? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"VEA"},"2":{"en":"VCA"},"3":{"en":"VDZ"},"4":{"en":"UDB"}},"answer":"1","solution":{"en":"1st letter: H → E → B → Y → V (−3)<br>2nd letter: O → S → W → A → E (+4)<br>3rd letter: M → J → G → D → A (−3)<br>Next = VEA<br><br><b>Hence, the correct answer is option (1): VEA.</b>","hi":"पहला अक्षर: H → E → B → Y → V (−3)<br>दूसरा अक्षर: O → S → W → A → E (+4)<br>तीसरा अक्षर: M → J → G → D → A (−3)<br>अगला = VEA<br><br><b>अतः सही उत्तर विकल्प (1): VEA है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":23,"local_id":"50023","quid":"Q1000071503","section":"REASONING","topic":"Statement, Assumption & Argument","question":{"en":"Read the given statement carefully and the following assumptions based on it. Decide which of the assumptions are implicit in the statement.<br><b>Statement:</b><br>For a project to be completed before the upcoming deadline, the team leader instructed all members to adopt an agile methodology for faster task execution.<br><b>Assumptions:</b><br>I. The project was previously running behind schedule due to the incompetence of the team members.<br>II. Adopting an agile methodology is conducive to increasing the speed of project completion. [SSC CGL 09/10/26 Shift 2]","hi":"दिए गए कथन और उस पर आधारित निम्नलिखित पूर्वधारणाओं को ध्यान से पढ़िए। तय कीजिए कि कौन-सी पूर्वधारणाएँ कथन में निहित हैं।<br><b>कथन:</b><br>आगामी समय-सीमा से पहले परियोजना पूरी करने के लिए, टीम लीडर ने सभी सदस्यों को कार्यों के तेज़ निष्पादन हेतु एजाइल पद्धति अपनाने का निर्देश दिया।<br><b>पूर्वधारणाएँ:</b><br>I. परियोजना पहले टीम सदस्यों की अक्षमता के कारण समय से पीछे चल रही थी।<br>II. एजाइल पद्धति अपनाना परियोजना पूरी करने की गति बढ़ाने में सहायक है। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Only Assumption I is implicit","hi":"केवल पूर्वधारणा I निहित है"},"2":{"en":"Both Assumptions I and II are implicit","hi":"पूर्वधारणाएँ I और II दोनों निहित हैं"},"3":{"en":"Neither Assumption I nor II is implicit","hi":"न तो पूर्वधारणा I और न ही II निहित है"},"4":{"en":"Only Assumption II is implicit","hi":"केवल पूर्वधारणा II निहित है"}},"answer":"4","solution":{"en":"Agile is adopted \"for faster task execution\", so II is implicit.<br>Nothing suggests the team was incompetent, so I is not implicit.<br><br><b>Hence, the correct answer is option (4): Only Assumption II is implicit.</b>","hi":"एजाइल \"कार्यों के तेज़ निष्पादन\" के लिए अपनाया गया, अतः II निहित है।<br>टीम की अक्षमता का कोई संकेत नहीं है, अतः I निहित नहीं है।<br><br><b>अतः सही उत्तर विकल्प (4): केवल पूर्वधारणा II निहित है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":24,"local_id":"50024","quid":"Q1000071504","section":"REASONING","topic":"Matrix","question":{"en":"Which of the following rows/columns are connected/related with each other in some way?<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">Rows</td><td style=\"border:1px solid #888;padding:3px 6px\">I</td><td style=\"border:1px solid #888;padding:3px 6px\">II</td><td style=\"border:1px solid #888;padding:3px 6px\">III</td><td style=\"border:1px solid #888;padding:3px 6px\">IV</td><td style=\"border:1px solid #888;padding:3px 6px\">V</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">I</td><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">3</td><td style=\"border:1px solid #888;padding:3px 6px\">7</td><td style=\"border:1px solid #888;padding:3px 6px\">6</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">II</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">16</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td><td style=\"border:1px solid #888;padding:3px 6px\">18</td><td style=\"border:1px solid #888;padding:3px 6px\">14</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">III</td><td style=\"border:1px solid #888;padding:3px 6px\">8</td><td style=\"border:1px solid #888;padding:3px 6px\">64</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td><td style=\"border:1px solid #888;padding:3px 6px\">144</td><td style=\"border:1px solid #888;padding:3px 6px\">132</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">IV</td><td style=\"border:1px solid #888;padding:3px 6px\">16</td><td style=\"border:1px solid #888;padding:3px 6px\">256</td><td style=\"border:1px solid #888;padding:3px 6px\">81</td><td style=\"border:1px solid #888;padding:3px 6px\">180</td><td style=\"border:1px solid #888;padding:3px 6px\">180</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">V</td><td style=\"border:1px solid #888;padding:3px 6px\">32</td><td style=\"border:1px solid #888;padding:3px 6px\">1024</td><td style=\"border:1px solid #888;padding:3px 6px\">243</td><td style=\"border:1px solid #888;padding:3px 6px\">324</td><td style=\"border:1px solid #888;padding:3px 6px\">508</td></tr></table> [SSC CGL 09/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सी पंक्तियाँ/स्तंभ किसी प्रकार एक-दूसरे से जुड़े/संबंधित हैं?<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">पंक्ति</td><td style=\"border:1px solid #888;padding:3px 6px\">I</td><td style=\"border:1px solid #888;padding:3px 6px\">II</td><td style=\"border:1px solid #888;padding:3px 6px\">III</td><td style=\"border:1px solid #888;padding:3px 6px\">IV</td><td style=\"border:1px solid #888;padding:3px 6px\">V</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">I</td><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">3</td><td style=\"border:1px solid #888;padding:3px 6px\">7</td><td style=\"border:1px solid #888;padding:3px 6px\">6</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">II</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">16</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td><td style=\"border:1px solid #888;padding:3px 6px\">18</td><td style=\"border:1px solid #888;padding:3px 6px\">14</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">III</td><td style=\"border:1px solid #888;padding:3px 6px\">8</td><td style=\"border:1px solid #888;padding:3px 6px\">64</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td><td style=\"border:1px solid #888;padding:3px 6px\">144</td><td style=\"border:1px solid #888;padding:3px 6px\">132</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">IV</td><td style=\"border:1px solid #888;padding:3px 6px\">16</td><td style=\"border:1px solid #888;padding:3px 6px\">256</td><td style=\"border:1px solid #888;padding:3px 6px\">81</td><td style=\"border:1px solid #888;padding:3px 6px\">180</td><td style=\"border:1px solid #888;padding:3px 6px\">180</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">V</td><td style=\"border:1px solid #888;padding:3px 6px\">32</td><td style=\"border:1px solid #888;padding:3px 6px\">1024</td><td style=\"border:1px solid #888;padding:3px 6px\">243</td><td style=\"border:1px solid #888;padding:3px 6px\">324</td><td style=\"border:1px solid #888;padding:3px 6px\">508</td></tr></table> [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Columns I, II and IV","hi":"स्तंभ I, II और IV"},"2":{"en":"Columns I, II and III","hi":"स्तंभ I, II और III"},"3":{"en":"Columns I, II and V","hi":"स्तंभ I, II और V"},"4":{"en":"Columns II, III and V","hi":"स्तंभ II, III और V"}},"answer":"2","solution":{"en":"For row n: Column I = 2ⁿ, Column II = 4ⁿ, Column III = 3ⁿ.<br>e.g. row II: 2² = 4, 4² = 16, 3² = 9<br>So Columns I, II and III are related.<br><br><b>Hence, the correct answer is option (2): Columns I, II and III.</b>","hi":"पंक्ति n के लिए: स्तंभ I = 2ⁿ, स्तंभ II = 4ⁿ, स्तंभ III = 3ⁿ<br>जैसे पंक्ति II: 2² = 4, 4² = 16, 3² = 9<br>अतः स्तंभ I, II और III संबंधित हैं।<br><br><b>अतः सही उत्तर विकल्प (2): स्तंभ I, II और III है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":25,"local_id":"50025","quid":"Q1000071505","section":"REASONING","topic":"Word Analogy","question":{"en":"Select the option that is related to the third word in the same way as the second word is related to the first word. (The words must be considered as meaningful English words and must not be related to each other based on the number of letters/number of consonants/vowels in the word.)<br><br>Scissors : Cut :: Needle : ? [SSC CGL 09/10/26 Shift 2]","hi":"उस विकल्प का चयन कीजिए जो तीसरे शब्द से उसी प्रकार संबंधित है जिस प्रकार दूसरा शब्द पहले शब्द से संबंधित है। (शब्दों को अर्थपूर्ण अंग्रेज़ी शब्दों के रूप में माना जाना चाहिए और उन्हें शब्द में अक्षरों की संख्या/व्यंजनों/स्वरों की संख्या के आधार पर एक-दूसरे से संबंधित नहीं किया जाना चाहिए।)<br><br>कैंची : काटना :: सुई : ? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Measure","hi":"मापना"},"2":{"en":"Sew","hi":"सिलना"},"3":{"en":"Paint","hi":"रंगना"},"4":{"en":"Dig","hi":"खोदना"}},"answer":"2","solution":{"en":"Scissors are used to cut.<br>A needle is used to sew.<br><br><b>Hence, the correct answer is option (2): Sew.</b>","hi":"कैंची का प्रयोग काटने के लिए होता है।<br>सुई का प्रयोग सिलने के लिए होता है।<br><br><b>अतः सही उत्तर विकल्प (2): सिलना है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"GK":{"seconds":900,"questions":[{"no":26,"local_id":"50026","quid":"Q1000071506","section":"GK","topic":"Economics: Microeconomics","question":{"en":"If the price of the commodity decreases from Rs. 100 to Rs. 105, and the quantity demanded decreases from 100 to 115, then what is the value of the price elasticity? [SSC CGL 09/10/26 Shift 2]","hi":"यदि किसी वस्तु की कीमत ₹100 से घटकर ₹105 हो जाती है और माँगी गई मात्रा 100 से घटकर 115 हो जाती है, तो कीमत लोच का मान क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"0.33"},"2":{"en":"3"},"3":{"en":"0.91"},"4":{"en":"1.09"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – 3</b><br>% change in quantity = \\(\\frac{115 - 100}{100} \\times 100 = 15\\%\\)<br>% change in price = \\(\\frac{105 - 100}{100} \\times 100 = 5\\%\\)<br>Price elasticity = \\(\\frac{15}{5}\\) = <b><u>3</u></b> (numerical value)<br><br><br><b><u>Important Points:</u></b><br>• \\(E_d = \\frac{\\%\\ \\text{change in quantity demanded}}{\\%\\ \\text{change in price}}\\).<br>• E<sub>d</sub> &gt; 1 – <b>elastic</b>; E<sub>d</sub> &lt; 1 – inelastic; E<sub>d</sub> = 1 – unitary elastic.<br>• Necessities have inelastic demand; luxuries have elastic demand.","hi":"<b>सही उत्तर: विकल्प (2) – 3</b><br>मात्रा में % परिवर्तन = \\(\\frac{115 - 100}{100} \\times 100 = 15\\%\\)<br>कीमत में % परिवर्तन = \\(\\frac{105 - 100}{100} \\times 100 = 5\\%\\)<br>कीमत लोच = \\(\\frac{15}{5}\\) = <b><u>3</u></b> (संख्यात्मक मान)<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• \\(E_d = \\frac{\\%\\ \\text{change in quantity demanded}}{\\%\\ \\text{change in price}}\\)।<br>• E<sub>d</sub> &gt; 1 – <b>लोचदार</b>; E<sub>d</sub> &lt; 1 – बेलोचदार; E<sub>d</sub> = 1 – इकाई लोच।<br>• अनिवार्य वस्तुओं की माँग बेलोचदार; विलासिता वस्तुओं की लोचदार होती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":27,"local_id":"50027","quid":"Q1000071507","section":"GK","topic":"Economics: Budget and Taxation","question":{"en":"An example of a direct tax is: [SSC CGL 09/10/26 Shift 2]","hi":"प्रत्यक्ष कर का एक उदाहरण है: [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Goods and&nbsp; services tax","hi":"वस्तु एवं सेवा कर"},"2":{"en":"Excise duty","hi":"उत्पाद शुल्क"},"3":{"en":"Corporate tax","hi":"निगम कर"},"4":{"en":"Central sales tax","hi":"केंद्रीय बिक्री कर"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Corporate tax</b><br>A <b>direct tax</b> is paid by the person on whom it is levied and cannot be shifted. <b><u>Corporate tax</u></b> on company profits is a direct tax; GST, excise and sales tax are indirect taxes.<br><br><br><b><u>Important Points:</u></b><br>• Other direct taxes: <b>income tax, wealth tax (abolished 2015), capital gains tax</b>.<br>• Direct taxes are administered by <b>CBDT</b>; indirect taxes by <b>CBIC</b>.<br>• The <b>Income-tax Act, 2025</b> replaces the 1961 Act from April 2026.","hi":"<b>सही उत्तर: विकल्प (3) – निगम कर</b><br><b>प्रत्यक्ष कर</b> उसी व्यक्ति द्वारा चुकाया जाता है जिस पर वह लगाया जाता है और इसे अन्य पर नहीं टाला जा सकता। कंपनी के लाभ पर <b><u>निगम कर</u></b> प्रत्यक्ष कर है; GST, उत्पाद शुल्क और बिक्री कर अप्रत्यक्ष कर हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• अन्य प्रत्यक्ष कर: <b>आयकर, संपत्ति कर (2015 में समाप्त), पूँजीगत लाभ कर</b>।<br>• प्रत्यक्ष कर <b>CBDT</b> और अप्रत्यक्ष कर <b>CBIC</b> प्रशासित करता है।<br>• <b>आयकर अधिनियम, 2025</b> अप्रैल 2026 से 1961 के अधिनियम का स्थान लेता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":28,"local_id":"50028","quid":"Q1000071508","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"Which Indian state is known for its traditional martial art, Kalaripayattu? [SSC CGL 09/10/26 Shift 2]","hi":"कौन-सा भारतीय राज्य अपनी पारंपरिक युद्ध कला कलारीपयट्टु के लिए जाना जाता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Maharashtra","hi":"महाराष्ट्र"},"2":{"en":"Kerala","hi":"केरल"},"3":{"en":"West Bengal","hi":"पश्चिम बंगाल"},"4":{"en":"Andhra Pradesh","hi":"आंध्र प्रदेश"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Kerala</b><br><b>Kalaripayattu</b>, one of the oldest martial arts in the world, originated in <b><u>Kerala</u></b>; it is practised in a training arena called <b>kalari</b>.<br><br><br><b><u>Important Points:</u></b><br>• Other martial arts: <b>Gatka</b> (Punjab), <b>Thang-Ta</b> (Manipur), <b>Silambam</b> (Tamil Nadu), <b>Mardani Khel</b> (Maharashtra).<br>• Kalaripayattu exponent <b>Meenakshi Amma</b> received the <b>Padma Shri (2017)</b>.<br>• The training arena <b>kalari</b> is traditionally built facing east.","hi":"<b>सही उत्तर: विकल्प (2) – केरल</b><br>विश्व की सबसे प्राचीन युद्ध कलाओं में से एक <b>कलारीपयट्टु</b> की उत्पत्ति <b><u>केरल</u></b> में हुई; इसका अभ्यास <b>कलरी</b> नामक प्रशिक्षण स्थल में होता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• अन्य युद्ध कलाएँ: <b>गतका</b> (पंजाब), <b>थांग-टा</b> (मणिपुर), <b>सिलंबम</b> (तमिलनाडु), <b>मर्दानी खेल</b> (महाराष्ट्र)।<br>• कलारीपयट्टु के लिए <b>मीनाक्षी अम्मा</b> को <b>पद्म श्री (2017)</b> मिला।<br>• प्रशिक्षण स्थल <b>कलरी</b> परंपरागत रूप से पूर्वमुखी बनाया जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":29,"local_id":"50029","quid":"Q1000071509","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"In which year was the first ever MotoGP race held in India, and at which circuit? [SSC CGL 09/10/26 Shift 2]","hi":"भारत में पहली बार MotoGP रेस किस वर्ष और किस सर्किट पर आयोजित हुई? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"2021, Madras Motor Race Track","hi":"2021, मद्रास मोटर रेस ट्रैक"},"2":{"en":"2022, Kari Motor Speedway","hi":"2022, कारी मोटर स्पीडवे"},"3":{"en":"2023, Buddh International Circuit","hi":"2023, बुद्ध इंटरनेशनल सर्किट"},"4":{"en":"2024, Hyderabad Street Circuit","hi":"2024, हैदराबाद स्ट्रीट सर्किट"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – 2023, Buddh International Circuit</b><br>India's first MotoGP race, the <b>Grand Prix of Bharat</b>, was held at the <b><u>Buddh International Circuit</u></b>, Greater Noida, in <b>September <u>2023</u></b>; it was won by <b>Marco Bezzecchi</b>.<br><br><br><b><u>Important Points:</u></b><br>• The Buddh circuit also hosted India's only <b>Formula 1 races (2011–2013)</b>.<br>• The circuit was designed by <b>Hermann Tilke</b>.<br>• MotoGP is governed by <b>FIM</b>.","hi":"<b>सही उत्तर: विकल्प (3) – 2023, बुद्ध इंटरनेशनल सर्किट</b><br>भारत की पहली MotoGP रेस, <b>ग्रैंड प्रिक्स ऑफ भारत</b>, <b>सितंबर <u>2023</u></b> में ग्रेटर नोएडा के <b><u>बुद्ध इंटरनेशनल सर्किट</u></b> पर हुई; इसे <b>मार्को बेज़ेची</b> ने जीता।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• बुद्ध सर्किट ने भारत की एकमात्र <b>फ़ॉर्मूला 1 रेसों (2011–2013)</b> की भी मेज़बानी की।<br>• सर्किट का डिज़ाइन <b>हरमन टिल्के</b> ने बनाया।<br>• MotoGP का शासी निकाय <b>FIM</b> है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":30,"local_id":"50030","quid":"Q1000071510","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"Which Indian woman boxer won a medal at the London 2012 Olympics? [SSC CGL 09/10/26 Shift 2]","hi":"लंदन 2012 ओलंपिक में किस भारतीय महिला मुक्केबाज़ ने पदक जीता? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Nikhat Zareen","hi":"निकहत ज़रीन"},"2":{"en":"Lovlina Borgohain","hi":"लवलीना बोरगोहेन"},"3":{"en":"Mary Kom","hi":"मैरी कॉम"},"4":{"en":"Sarita Devi","hi":"सरिता देवी"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Mary Kom</b><br><b><u>M.C. Mary Kom</u></b> won <b>bronze</b> in the women's flyweight (51 kg) at <b>London 2012</b>, the first Olympics to include women's boxing.<br><br><br><b><u>Important Points:</u></b><br>• Mary Kom is a <b>six-time World Champion</b>; called <b>\"Magnificent Mary\"</b>.<br>• <b>Lovlina Borgohain</b> won bronze at <b>Tokyo 2020</b>.<br>• <b>Nikhat Zareen</b> is a two-time World Champion (2022, 2023).","hi":"<b>सही उत्तर: विकल्प (3) – मैरी कॉम</b><br><b><u>एम.सी. मैरी कॉम</u></b> ने <b>लंदन 2012</b> में महिला फ्लाईवेट (51 kg) में <b>कांस्य</b> जीता; यह महिला मुक्केबाज़ी वाला पहला ओलंपिक था।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मैरी कॉम <b>छह बार की विश्व चैंपियन</b> हैं; उन्हें <b>\"मैग्निफ़िसेंट मैरी\"</b> कहा जाता है।<br>• <b>लवलीना बोरगोहेन</b> ने <b>टोक्यो 2020</b> में कांस्य जीता।<br>• <b>निकहत ज़रीन</b> दो बार की विश्व चैंपियन (2022, 2023) हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":31,"local_id":"50031","quid":"Q1000071511","section":"GK","topic":"Current Affairs: Awards and Honours (Current)","question":{"en":"Which city retained its title as the cleanest city in India for the 7<sup>th</sup>consecutive year in Swachh Survekshan 2024? [SSC CGL 09/10/26 Shift 2]","hi":"स्वच्छ सर्वेक्षण 2024 में किस शहर ने लगातार 7वें वर्ष भारत के सबसे स्वच्छ शहर का खिताब बरकरार रखा? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Mysuru","hi":"मैसूरु"},"2":{"en":"Surat","hi":"सूरत"},"3":{"en":"Indore","hi":"इंदौर"},"4":{"en":"Bhopal","hi":"भोपाल"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Indore</b><br><b><u>Indore</u></b> was ranked India's cleanest city for the <b>seventh consecutive time</b> in the Swachh Survekshan awards announced in <b>January 2024</b> (shared with Surat).<br><br><br><b><u>Important Points:</u></b><br>• Swachh Survekshan is conducted by the <b>Ministry of Housing and Urban Affairs</b> since <b>2016</b>.<br>• In Swachh Survekshan 2024–25, Indore was placed in the new <b>\"Super Swachh League\"</b>.<br>• Swachh Bharat Mission was launched on <b>2 October 2014</b>.","hi":"<b>सही उत्तर: विकल्प (3) – इंदौर</b><br><b>जनवरी 2024</b> में घोषित स्वच्छ सर्वेक्षण पुरस्कारों में <b><u>इंदौर</u></b> को लगातार <b>सातवीं बार</b> भारत का सबसे स्वच्छ शहर चुना गया (सूरत के साथ साझा)।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• स्वच्छ सर्वेक्षण <b>2016</b> से <b>आवास और शहरी कार्य मंत्रालय</b> द्वारा किया जाता है।<br>• स्वच्छ सर्वेक्षण 2024–25 में इंदौर को नई <b>\"सुपर स्वच्छ लीग\"</b> में रखा गया।<br>• स्वच्छ भारत मिशन <b>2 अक्टूबर 2014</b> को शुरू हुआ।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":32,"local_id":"50032","quid":"Q1000071512","section":"GK","topic":"Geography: Peninsular Rivers","question":{"en":"Which of the following is the largest river system of Peninsular India? [SSC CGL 09/10/26 Shift 2]","hi":"निम्नलिखित में से प्रायद्वीपीय भारत का सबसे बड़ा नदी तंत्र कौन-सा है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Godavari River System","hi":"गोदावरी नदी तंत्र"},"2":{"en":"Krishna River System","hi":"कृष्णा नदी तंत्र"},"3":{"en":"Kaveri River System","hi":"कावेरी नदी तंत्र"},"4":{"en":"Ganga River System","hi":"गंगा नदी तंत्र"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Godavari River System</b><br>The <b><u>Godavari</u></b> is the largest Peninsular river system (about <b>1,465 km</b>), rising at Trimbakeshwar near Nashik; it is called the <b>\"Dakshin Ganga\"</b>.<br><br><br><b><u>Important Points:</u></b><br>• Ganga is a <b>Himalayan</b> river system, not a Peninsular one.<br>• Tributaries: <b>Purna, Wardha, Pranhita, Manjra, Wainganga, Indravati</b>.<br>• <b>Polavaram</b> project is on the Godavari (Andhra Pradesh).","hi":"<b>सही उत्तर: विकल्प (1) – गोदावरी नदी तंत्र</b><br><b><u>गोदावरी</u></b> सबसे बड़ा प्रायद्वीपीय नदी तंत्र (लगभग <b>1,465 km</b>) है, जो नासिक के निकट त्र्यंबकेश्वर से निकलती है; इसे <b>\"दक्षिण गंगा\"</b> कहा जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• गंगा <b>हिमालयी</b> नदी तंत्र है, प्रायद्वीपीय नहीं।<br>• सहायक नदियाँ: <b>पूर्णा, वर्धा, प्राणहिता, मांजरा, वैनगंगा, इंद्रावती</b>।<br>• <b>पोलावरम</b> परियोजना गोदावरी (आंध्र प्रदेश) पर है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":33,"local_id":"50033","quid":"Q1000071513","section":"GK","topic":"Ancient History: Vedic Age","question":{"en":"The uniqueness of the Rigveda lies in its: [SSC CGL 09/10/26 Shift 2]","hi":"ऋग्वेद की विशिष्टता उसके किस गुण में है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Ritual procedures","hi":"अनुष्ठान प्रक्रियाएँ"},"2":{"en":"Multiperiod compilation","hi":"बहु-कालिक संकलन"},"3":{"en":"Scientific content","hi":"वैज्ञानिक सामग्री"},"4":{"en":"Use of Dravidian terms","hi":"द्रविड़ शब्दों का उपयोग"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Multiperiod compilation</b><br>The Rigveda's 10 mandalas were composed over a long period – <b>Mandalas II–VII</b> (family books) are the oldest, while <b>I and X</b> are later additions. This <b><u>multi-period compilation</u></b> makes it unique.<br><br><br><b><u>Important Points:</u></b><br>• The Rigveda has <b>1,028 hymns</b> in 10 mandalas.<br>• The <b>Purusha Sukta</b> (Mandala X) first mentions the four varnas.<br>• Mandala IX is devoted entirely to <b>Soma</b>.","hi":"<b>सही उत्तर: विकल्प (2) – बहु-कालिक संकलन</b><br>ऋग्वेद के 10 मंडल लंबी अवधि में रचे गए – <b>मंडल II–VII</b> (कुल-मंडल) सबसे प्राचीन हैं, जबकि <b>I और X</b> बाद में जोड़े गए। यही <b><u>बहु-कालिक संकलन</u></b> इसे विशिष्ट बनाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• ऋग्वेद में 10 मंडलों में <b>1,028 सूक्त</b> हैं।<br>• <b>पुरुष सूक्त</b> (मंडल X) में पहली बार चार वर्णों का उल्लेख है।<br>• मंडल IX पूर्णतः <b>सोम</b> को समर्पित है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":34,"local_id":"50034","quid":"Q1000071514","section":"GK","topic":"Static GK: Music and Musical Instruments","question":{"en":"<b>Fill in the blanks:</b><br>The Mizo wind instrument Rawchhem, which resembles the Scottish bagpipe, produces different musical notes when the musician controls the _____. [SSC CGL 09/10/26 Shift 2]","hi":"<b>रिक्त स्थान भरिए:</b><br>स्कॉटिश बैगपाइप जैसा दिखने वाला मिज़ो सुषिर वाद्य रॉछेम विभिन्न स्वर तब उत्पन्न करता है जब संगीतकार _____ को नियंत्रित करता है। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"bamboo reeds","hi":"बाँस की नलियाँ"},"2":{"en":"leather valves","hi":"चमड़े के वाल्व"},"3":{"en":"brass strings","hi":"पीतल के तार"},"4":{"en":"finger holes","hi":"उंगली के छिद्र"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – finger holes</b><br>The <b>Rawchhem</b> is a Mizo wind instrument made of a dried gourd with bamboo pipes; the player produces different notes by <b><u>controlling the finger holes</u></b>.<br><br><br><b><u>Important Points:</u></b><br>• Other Mizo instruments: <b>Khuang</b> (drum), <b>Darbu</b> (gong set), <b>Tuiumdar</b>.<br>• Wind instruments are called <b>Sushir Vadya</b> in Indian classification.<br>• Indian classification (Natyashastra): <b>Tata, Sushira, Avanaddha, Ghana</b>.","hi":"<b>सही उत्तर: विकल्प (4) – उंगली के छिद्र</b><br><b>रॉछेम</b> एक मिज़ो सुषिर वाद्य है, जो बाँस की नलियों वाले सूखे लौकी से बनता है; वादक <b><u>उंगली के छिद्रों को नियंत्रित</u></b> करके विभिन्न स्वर निकालता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• अन्य मिज़ो वाद्य: <b>खुआंग</b> (ढोल), <b>दरबू</b> (घंटा समूह), <b>तुइउमदर</b>।<br>• भारतीय वर्गीकरण में सुषिर वाद्य फूँक से बजते हैं।<br>• भारतीय वर्गीकरण (नाट्यशास्त्र): <b>तत, सुषिर, अवनद्ध, घन</b>।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":35,"local_id":"50035","quid":"Q1000071515","section":"GK","topic":"Current Affairs: Summits and Conferences","question":{"en":"<b>Consider the following statements regarding India’s participation in the 9<sup>th</sup> BRICS Industry Ministers’ Meeting held in 2025:</b><br>1) India launched the BRICS Startup Knowledge Hub in May 2025 to boost rural digital connectivity.<br>2) India highlighted that MSMEs contributed over 45% to exports and employed 25+ crore people in 2023–24.<br><b>Which of the above statements is/are correct?</b> [SSC CGL 09/10/26 Shift 2]","hi":"<b>2025 में आयोजित 9वीं ब्रिक्स उद्योग मंत्रियों की बैठक में भारत की भागीदारी के संबंध में निम्नलिखित कथनों पर विचार कीजिए:</b><br>1) भारत ने ग्रामीण डिजिटल कनेक्टिविटी बढ़ाने के लिए मई 2025 में ब्रिक्स स्टार्टअप नॉलेज हब शुरू किया।<br>2) भारत ने रेखांकित किया कि 2023–24 में MSMEs ने निर्यात में 45% से अधिक योगदान दिया और 25+ करोड़ लोगों को रोज़गार दिया।<br><b>उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?</b> [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Only 1 is correct","hi":"केवल 1 सही है"},"2":{"en":"Only 2 is correct","hi":"केवल 2 सही है"},"3":{"en":"Both 1 and 2 are correct","hi":"1 और 2 दोनों सही हैं"},"4":{"en":"Neither 1 nor 2 is correct","hi":"न तो 1 और न ही 2 सही है"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Only 2 is correct</b><br>At the <b>9<sup>th</sup> BRICS Industry Ministers' Meeting (Brasília, May 2025)</b>, India highlighted that <b>MSMEs contribute over 45% of exports</b> and employ more than 25 crore people – statement 2 is correct. The BRICS Startup Knowledge Hub was not launched at this meeting for rural connectivity – statement 1 is wrong. Hence <b><u>Only 2</u></b>.<br><br><br><b><u>Important Points:</u></b><br>• Brazil held the <b>BRICS chair in 2025</b>; India holds it in <b>2026</b>.<br>• MSMEs are regulated by the <b>MSMED Act, 2006</b>; registration on the <b>Udyam</b> portal.<br>• The <b>BRICS Startup Forum</b> was proposed by India to boost start-up cooperation.","hi":"<b>सही उत्तर: विकल्प (2) – केवल 2 सही है</b><br><b>9वीं ब्रिक्स उद्योग मंत्रियों की बैठक (ब्रासीलिया, मई 2025)</b> में भारत ने रेखांकित किया कि <b>MSMEs निर्यात में 45% से अधिक योगदान</b> देते हैं और 25 करोड़ से अधिक लोगों को रोज़गार देते हैं – कथन 2 सही है। ब्रिक्स स्टार्टअप नॉलेज हब इस बैठक में ग्रामीण कनेक्टिविटी के लिए शुरू नहीं हुआ – कथन 1 गलत है। अतः <b><u>केवल 2</u></b>।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• 2025 में <b>ब्रिक्स अध्यक्षता ब्राज़ील</b> के पास थी; <b>2026</b> में भारत के पास है।<br>• MSMEs <b>MSMED अधिनियम, 2006</b> से विनियमित; पंजीकरण <b>उद्यम</b> पोर्टल पर।<br>• स्टार्टअप सहयोग बढ़ाने के लिए भारत ने <b>ब्रिक्स स्टार्टअप फ़ोरम</b> का प्रस्ताव रखा।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":36,"local_id":"50036","quid":"Q1000071516","section":"GK","topic":"Economics: Five Year Plan and Industrial Policy Resolution","question":{"en":"Why is Indian planning considered a democratic political process? [SSC CGL 09/10/26 Shift 2]","hi":"भारतीय नियोजन को लोकतांत्रिक राजनीतिक प्रक्रिया क्यों माना जाता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Because only elected officials approve the budget","hi":"क्योंकि केवल निर्वाचित अधिकारी बजट स्वीकृत करते हैं"},"2":{"en":"Because the planning process is secretive and efficient","hi":"क्योंकि नियोजन प्रक्रिया गुप्त और कुशल है"},"3":{"en":"Because it is driven by market forces, not politics","hi":"क्योंकि यह राजनीति नहीं, बाज़ार शक्तियों से संचालित है"},"4":{"en":"Because it undergoes parliamentary presentation and public input","hi":"क्योंकि यह संसद में प्रस्तुत होती है और जनता की राय ली जाती है"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Because it undergoes parliamentary presentation and public input</b><br>Indian plans were discussed and approved through democratic institutions – the <b>National Development Council</b>, the <b>Parliament</b> and public consultation – so planning was a democratic process that <b><u>undergoes parliamentary presentation and public input</u></b>.<br><br><br><b><u>Important Points:</u></b><br>• The <b>National Development Council (1952)</b> gave final approval to Five-Year Plans.<br>• Indian planning was <b>indicative</b> in a mixed economy, unlike the Soviet <b>imperative</b> planning.<br>• <b>NITI Aayog</b> follows a bottom-up approach of <b>cooperative federalism</b>.","hi":"<b>सही उत्तर: विकल्प (4) – क्योंकि यह संसद में प्रस्तुत होती है और जनता की राय ली जाती है</b><br>भारतीय योजनाएँ लोकतांत्रिक संस्थाओं – <b>राष्ट्रीय विकास परिषद</b>, <b>संसद</b> और जन-परामर्श – के माध्यम से चर्चा और स्वीकृति के बाद लागू होती थीं, अतः नियोजन ऐसी लोकतांत्रिक प्रक्रिया थी जो <b><u>संसद में प्रस्तुत होती है और जनता की राय लेती है</u></b>।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>राष्ट्रीय विकास परिषद (1952)</b> पंचवर्षीय योजनाओं को अंतिम स्वीकृति देती थी।<br>• भारतीय नियोजन मिश्रित अर्थव्यवस्था में <b>निर्देशात्मक (Indicative)</b> था, सोवियत <b>आदेशात्मक</b> नियोजन से भिन्न।<br>• <b>नीति आयोग</b> <b>सहकारी संघवाद</b> का नीचे-से-ऊपर दृष्टिकोण अपनाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":37,"local_id":"50037","quid":"Q1000071517","section":"GK","topic":"Ancient History: Indus Valley Civilization","question":{"en":"What was a unique feature of the bricks used in the buildings of Mohenjo-Daro? [SSC CGL 09/10/26 Shift 2]","hi":"मोहनजोदड़ो की इमारतों में प्रयुक्त ईंटों की एक अनोखी विशेषता क्या थी? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Standardized dimensional ratio","hi":"मानकीकृत आयामी अनुपात"},"2":{"en":"Brightly painted with natural dyes","hi":"प्राकृतिक रंगों से चमकीले रंगे"},"3":{"en":"Completely spherical shape","hi":"पूर्णतः गोलाकार आकार"},"4":{"en":"Made using glass","hi":"काँच से निर्मित"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Standardized dimensional ratio</b><br>Harappan bricks followed a <b><u>standardised ratio of 1:2:4</u></b> (thickness : width : length) across all sites, showing uniform town planning.<br><br><br><b><u>Important Points:</u></b><br>• Mostly <b>baked (burnt) bricks</b> were used at Mohenjo-daro; <b>Kalibangan</b> used mud bricks.<br>• The <b>Great Bath</b> at Mohenjo-daro was made watertight with <b>bitumen</b>.<br>• Weights were also standardised (binary system, multiples of 16).","hi":"<b>सही उत्तर: विकल्प (1) – मानकीकृत आयामी अनुपात</b><br>हड़प्पाई ईंटें सभी स्थलों पर <b><u>1:2:4 के मानकीकृत अनुपात</u></b> (मोटाई : चौड़ाई : लंबाई) में थीं, जो एकसमान नगर नियोजन दर्शाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मोहनजोदड़ो में अधिकतर <b>पकी ईंटें</b> प्रयुक्त हुईं; <b>कालीबंगा</b> में कच्ची ईंटें।<br>• मोहनजोदड़ो के <b>विशाल स्नानागार</b> को <b>बिटुमेन</b> से जलरोधी बनाया गया।<br>• माप-तौल भी मानकीकृत थे (द्विआधारी प्रणाली, 16 के गुणज)।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":38,"local_id":"50038","quid":"Q1000071518","section":"GK","topic":"Geography: Forest and Grassland","question":{"en":"Consider the following pairs of States and their share in India’s mangrove coverage and choose the <b>correct</b> option:<br>1.Gujarat — 23.66%<br>2.Odisha — 12.39% [SSC CGL 09/10/26 Shift 2]","hi":"राज्यों और भारत के मैंग्रोव आवरण में उनके हिस्से के निम्नलिखित युग्मों पर विचार कीजिए और <b>सही</b> विकल्प चुनिए:<br>1. गुजरात — 23.66%<br>2. ओडिशा — 12.39% [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Only 1","hi":"केवल 1"},"2":{"en":"Only 2","hi":"केवल 2"},"3":{"en":"Both 1 and 2 are correct","hi":"1 और 2 दोनों सही हैं"},"4":{"en":"Neither 1 nor 2 is correct","hi":"न तो 1 और न ही 2 सही है"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Only 1</b><br>As per the India State of Forest Report, <b>Gujarat</b> has about <b>23.66%</b> of India's mangrove cover – correct. The <b>12.39%</b> share belongs to <b>Andaman &amp; Nicobar Islands</b>, not Odisha. Hence <b><u>Only 1</u></b>.<br><br><br><b><u>Important Points:</u></b><br>• <b>West Bengal</b> has the largest share (about 42%) due to the <b>Sundarbans</b>.<br>• India's total mangrove cover is about <b>4,990 sq km</b> (~0.15% of area).<br>• <b>Bhitarkanika</b> (Odisha) is the second-largest mangrove ecosystem in India.","hi":"<b>सही उत्तर: विकल्प (1) – केवल 1</b><br>भारत वन स्थिति रिपोर्ट के अनुसार <b>गुजरात</b> में भारत के मैंग्रोव आवरण का लगभग <b>23.66%</b> है – सही। <b>12.39%</b> हिस्सा <b>अंडमान और निकोबार द्वीप समूह</b> का है, ओडिशा का नहीं। अतः <b><u>केवल 1</u></b>।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>सुंदरबन</b> के कारण <b>पश्चिम बंगाल</b> का हिस्सा सबसे अधिक (लगभग 42%) है।<br>• भारत का कुल मैंग्रोव आवरण लगभग <b>4,990 वर्ग km</b> (~0.15% क्षेत्रफल) है।<br>• <b>भितरकनिका</b> (ओडिशा) भारत का दूसरा सबसे बड़ा मैंग्रोव पारितंत्र है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":39,"local_id":"50039","quid":"Q1000071519","section":"GK","topic":"Polity: Centre-State Relations","question":{"en":"Under which Article of the Indian Constitution can the Union government issue directions to States in certain matters? [SSC CGL 09/10/26 Shift 2]","hi":"भारतीय संविधान के किस अनुच्छेद के तहत केंद्र सरकार कुछ मामलों में राज्यों को निर्देश दे सकती है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Article 250","hi":"अनुच्छेद 250"},"2":{"en":"Article 254","hi":"अनुच्छेद 254"},"3":{"en":"Article 256","hi":"अनुच्छेद 256"},"4":{"en":"Article 258","hi":"अनुच्छेद 258"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Article 256</b><br><b><u>Article 256</u></b> requires States to exercise their executive power so as to ensure compliance with laws made by Parliament, and empowers the Union to <b>give directions</b> to States for this purpose.<br><br><br><b><u>Important Points:</u></b><br>• <b>Art. 257</b> – Union control over States in certain cases (communications, railways).<br>• <b>Art. 365</b> – if a State fails to comply with Union directions, President's Rule may follow.<br>• <b>Art. 258</b> – Union may entrust functions to States.","hi":"<b>सही उत्तर: विकल्प (3) – अनुच्छेद 256</b><br><b><u>अनुच्छेद 256</u></b> राज्यों को अपनी कार्यपालिका शक्ति का प्रयोग इस प्रकार करने को कहता है कि संसद के कानूनों का पालन सुनिश्चित हो, और इस हेतु केंद्र को राज्यों को <b>निर्देश देने</b> का अधिकार देता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>अनु. 257</b> – कुछ मामलों में राज्यों पर केंद्र का नियंत्रण (संचार, रेलवे)।<br>• <b>अनु. 365</b> – राज्य द्वारा केंद्र के निर्देशों का पालन न करने पर राष्ट्रपति शासन लग सकता है।<br>• <b>अनु. 258</b> – केंद्र राज्यों को कार्य सौंप सकता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":40,"local_id":"50040","quid":"Q1000071520","section":"GK","topic":"Polity: Local Government","question":{"en":"Under which article of the Indian Constitution is the State Legislature empowered to make provisions for the maintenance and auditing of Panchayat accounts? [SSC CGL 09/10/26 Shift 2]","hi":"भारतीय संविधान के किस अनुच्छेद के तहत राज्य विधानमंडल को पंचायत लेखों के रखरखाव और लेखा-परीक्षा के लिए प्रावधान करने का अधिकार है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Article 239B","hi":"अनुच्छेद 239B"},"2":{"en":"Article 224A","hi":"अनुच्छेद 224A"},"3":{"en":"Article 243J","hi":"अनुच्छेद 243J"},"4":{"en":"Article 279A","hi":"अनुच्छेद 279A"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Article 243J</b><br><b><u>Article 243J</u></b> (Part IX) empowers the State Legislature to make provisions for the <b>maintenance and audit of accounts of Panchayats</b>.<br><br><br><b><u>Important Points:</u></b><br>• <b>Art. 243I</b> – State Finance Commission; <b>Art. 243K</b> – State Election Commission.<br>• <b>Art. 239B</b> – ordinance power of UT administrators; <b>Art. 224A</b> – retired judges at High Court sittings.<br>• <b>Art. 279A</b> – GST Council.","hi":"<b>सही उत्तर: विकल्प (3) – अनुच्छेद 243J</b><br><b><u>अनुच्छेद 243J</u></b> (भाग IX) राज्य विधानमंडल को <b>पंचायतों के लेखों के रखरखाव और लेखा-परीक्षा</b> के प्रावधान करने का अधिकार देता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>अनु. 243I</b> – राज्य वित्त आयोग; <b>अनु. 243K</b> – राज्य निर्वाचन आयोग।<br>• <b>अनु. 239B</b> – UT प्रशासकों की अध्यादेश शक्ति; <b>अनु. 224A</b> – उच्च न्यायालय में सेवानिवृत्त न्यायाधीश।<br>• <b>अनु. 279A</b> – GST परिषद।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":41,"local_id":"50041","quid":"Q1000071521","section":"GK","topic":"Geography: Minerals","question":{"en":"Which location in Rajasthan is known for uranium deposits? [SSC CGL 09/10/26 Shift 2]","hi":"राजस्थान का कौन-सा स्थान यूरेनियम भंडार के लिए जाना जाता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Jaisalmer","hi":"जैसलमेर"},"2":{"en":"Udaipur","hi":"उदयपुर"},"3":{"en":"Kota","hi":"कोटा"},"4":{"en":"Bikaner","hi":"बीकानेर"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Udaipur</b><br>Uranium deposits in Rajasthan occur in <b><u>Udaipur</u></b> district (Umra) and in the <b>Rohil</b> area of Sikar.<br><br><br><b><u>Important Points:</u></b><br>• India's major uranium mine: <b>Jaduguda (Jharkhand)</b>, run by <b>UCIL</b>.<br>• Large deposits also at <b>Tummalapalle (Andhra Pradesh)</b>.<br>• <b>Kota</b> (Rawatbhata) has a nuclear power station.","hi":"<b>सही उत्तर: विकल्प (2) – उदयपुर</b><br>राजस्थान में यूरेनियम के भंडार <b><u>उदयपुर</u></b> ज़िले (उमरा) और सीकर के <b>रोहिल</b> क्षेत्र में पाए जाते हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• भारत की प्रमुख यूरेनियम खान: <b>जादूगोड़ा (झारखंड)</b>, जिसे <b>UCIL</b> चलाता है।<br>• बड़े भंडार <b>तुम्मलापल्ले (आंध्र प्रदेश)</b> में भी हैं।<br>• <b>कोटा</b> (रावतभाटा) में परमाणु विद्युत केंद्र है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":42,"local_id":"50042","quid":"Q1000071522","section":"GK","topic":"Polity: Emergency & Constitutional Amendment","question":{"en":"Under Article 358 of the Indian Constitution, the suspension of Article 19 during a National Emergency operates only when the Emergency is proclaimed on which ground? [SSC CGL 09/10/26 Shift 2]","hi":"भारतीय संविधान के अनुच्छेद 358 के तहत राष्ट्रीय आपातकाल के दौरान अनुच्छेद 19 का निलंबन केवल तभी लागू होता है जब आपातकाल किस आधार पर घोषित किया गया हो? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"External aggression or war","hi":"बाहरी आक्रमण या युद्ध"},"2":{"en":"Financial instability or economic crisis","hi":"वित्तीय अस्थिरता या आर्थिक संकट"},"3":{"en":"Constitutional breakdown or failure of governance","hi":"संवैधानिक तंत्र की विफलता या शासन की विफलता"},"4":{"en":"Armed rebellion or internal disturbance","hi":"सशस्त्र विद्रोह या आंतरिक अशांति"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – External aggression or war</b><br>After the <b>44<sup>th</sup> Amendment (1978)</b>, Article 358 suspends Article 19 automatically only when the National Emergency is declared on the ground of <b><u>war or external aggression</u></b>, not armed rebellion.<br><br><br><b><u>Important Points:</u></b><br>• <b>Article 359</b> – President may suspend enforcement of other FRs, except <b>Articles 20 and 21</b>.<br>• The 44<sup>th</sup> Amendment replaced \"internal disturbance\" with <b>\"armed rebellion\"</b>.<br>• National Emergency was declared in <b>1962, 1971 and 1975</b>.","hi":"<b>सही उत्तर: विकल्प (1) – बाहरी आक्रमण या युद्ध</b><br><b>44वें संशोधन (1978)</b> के बाद अनुच्छेद 358 अनुच्छेद 19 को स्वतः केवल तभी निलंबित करता है जब राष्ट्रीय आपातकाल <b><u>युद्ध या बाहरी आक्रमण</u></b> के आधार पर घोषित हो, सशस्त्र विद्रोह पर नहीं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>अनुच्छेद 359</b> – राष्ट्रपति <b>अनुच्छेद 20 और 21</b> को छोड़कर अन्य मौलिक अधिकारों का प्रवर्तन निलंबित कर सकते हैं।<br>• 44वें संशोधन ने \"आंतरिक अशांति\" के स्थान पर <b>\"सशस्त्र विद्रोह\"</b> रखा।<br>• राष्ट्रीय आपातकाल <b>1962, 1971 और 1975</b> में घोषित हुआ।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":43,"local_id":"50043","quid":"Q1000071523","section":"GK","topic":"Geography: Minerals","question":{"en":"Which of the following is the second-largest coalfield in India after Jharia? [SSC CGL 09/10/26 Shift 2]","hi":"झरिया के बाद भारत का दूसरा सबसे बड़ा कोयला क्षेत्र निम्नलिखित में से कौन-सा है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Raniganj coal field","hi":"रानीगंज कोयला क्षेत्र"},"2":{"en":"Bokaro coal field","hi":"बोकारो कोयला क्षेत्र"},"3":{"en":"Giridih coal field","hi":"गिरिडीह कोयला क्षेत्र"},"4":{"en":"Karanpura coal field","hi":"करनपुरा कोयला क्षेत्र"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Raniganj coal field</b><br><b><u>Raniganj</u></b> (West Bengal) is the <b>second-largest</b> coalfield in India after <b>Jharia</b>; it is also the oldest, with mining since 1774.<br><br><br><b><u>Important Points:</u></b><br>• Jharia (Jharkhand) is the largest storehouse of <b>coking coal</b>.<br>• Most Indian coal is <b>Gondwana coal</b> (about 98%); Tertiary coal is found in the North-East.<br>• <b>Coal India Limited</b> HQ is in <b>Kolkata</b>.","hi":"<b>सही उत्तर: विकल्प (1) – रानीगंज कोयला क्षेत्र</b><br><b><u>रानीगंज</u></b> (पश्चिम बंगाल) <b>झरिया</b> के बाद भारत का <b>दूसरा सबसे बड़ा</b> कोयला क्षेत्र है; यह सबसे पुराना भी है, जहाँ 1774 से खनन होता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• झरिया (झारखंड) <b>कोकिंग कोयले</b> का सबसे बड़ा भंडार है।<br>• भारत का अधिकांश कोयला <b>गोंडवाना कोयला</b> (लगभग 98%) है; तृतीयक कोयला पूर्वोत्तर में मिलता है।<br>• <b>कोल इंडिया लिमिटेड</b> का मुख्यालय <b>कोलकाता</b> में है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":44,"local_id":"50044","quid":"Q1000071524","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"In which city was the first-ever Asian Games held in 1951? [SSC CGL 09/10/26 Shift 2]","hi":"1951 में पहले एशियाई खेल किस शहर में आयोजित हुए? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Tokyo, Japan","hi":"टोक्यो, जापान"},"2":{"en":"Bangkok, Thailand","hi":"बैंकॉक, थाईलैंड"},"3":{"en":"New Delhi, India","hi":"नई दिल्ली, भारत"},"4":{"en":"Seoul, South Korea","hi":"सियोल, दक्षिण कोरिया"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – New Delhi, India</b><br>The first <b>Asian Games</b> were held in <b><u>New Delhi</u></b> from <b>4 to 11 March 1951</b> at the National Stadium; India finished second in the medal table.<br><br><br><b><u>Important Points:</u></b><br>• The idea was proposed by <b>G.D. Sondhi</b>; India also hosted the <b>1982</b> Asian Games.<br>• The Games are held every <b>four years</b>; governed by the <b>Olympic Council of Asia</b>.<br>• The <b>2026</b> Asian Games are being held in <b>Aichi–Nagoya, Japan</b>.","hi":"<b>सही उत्तर: विकल्प (3) – नई दिल्ली, भारत</b><br>पहले <b>एशियाई खेल</b> <b>4 से 11 मार्च 1951</b> तक <b><u>नई दिल्ली</u></b> के नेशनल स्टेडियम में हुए; भारत पदक तालिका में दूसरे स्थान पर रहा।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• इसका विचार <b>जी.डी. सोंधी</b> ने दिया; भारत ने <b>1982</b> के एशियाई खेलों की भी मेज़बानी की।<br>• खेल हर <b>चार वर्ष</b> में होते हैं; शासी निकाय <b>एशियाई ओलंपिक परिषद</b>।<br>• <b>2026</b> एशियाई खेल <b>आइची–नागोया, जापान</b> में हो रहे हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":45,"local_id":"50045","quid":"Q1000071525","section":"GK","topic":"Biology: Plant and Animal Kingdom","question":{"en":"Consider the following statements regarding the Buff-tip moth:<br>1. The larvae of the buff-tip moth are capable of stripping an entire tree bare within a few weeks.<br>2. “Phalera cf. bucephala” is the scientific name of the buff-tip moth.<br>Which of the statements given above is/are <b>correct</b>? [SSC CGL 09/10/26 Shift 2]","hi":"बफ़-टिप पतंगे के संबंध में निम्नलिखित कथनों पर विचार कीजिए:<br>1. बफ़-टिप पतंगे के लार्वा कुछ ही सप्ताहों में पूरे पेड़ की पत्तियाँ खा सकते हैं।<br>2. “फलेरा cf. बुसेफ़ाला” बफ़-टिप पतंगे का वैज्ञानिक नाम है।<br>ऊपर दिए गए कथनों में से कौन-सा/से <b>सही</b> है/हैं? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"1 only","hi":"केवल 1"},"2":{"en":"2 only","hi":"केवल 2"},"3":{"en":"Both 1 and 2","hi":"1 और 2 दोनों"},"4":{"en":"Neither 1 nor 2","hi":"न तो 1 और न ही 2"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Both 1 and 2</b><br>The <b>buff-tip moth</b> (<i>Phalera bucephala</i>) has gregarious caterpillars that can <b>defoliate an entire tree</b> within weeks. Its scientific name is <i>Phalera bucephala</i> (written \"cf.\" when identification is provisional). Both statements are correct: <b><u>Both 1 and 2</u></b>.<br><br><br><b><u>Important Points:</u></b><br>• The moth's wings look like a <b>broken birch twig</b>, giving it excellent camouflage.<br>• Moths and butterflies belong to the order <b>Lepidoptera</b>.<br>• \"cf.\" (confer) is used when the species identity is <b>not fully confirmed</b>.","hi":"<b>सही उत्तर: विकल्प (3) – 1 और 2 दोनों</b><br><b>बफ़-टिप पतंगे</b> (<i>फलेरा बुसेफ़ाला</i>) के समूह में रहने वाले लार्वा कुछ सप्ताहों में <b>पूरे पेड़ को पत्तीविहीन</b> कर सकते हैं। इसका वैज्ञानिक नाम <i>फलेरा बुसेफ़ाला</i> है (पहचान अस्थायी होने पर \"cf.\" लिखा जाता है)। दोनों कथन सही हैं: <b><u>1 और 2 दोनों</u></b>।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• इस पतंगे के पंख <b>टूटी भोजपत्र टहनी</b> जैसे दिखते हैं, जिससे यह उत्कृष्ट छलावरण करता है।<br>• पतंगे और तितलियाँ <b>लेपिडोप्टेरा</b> गण से संबंधित हैं।<br>• \"cf.\" (confer) तब प्रयोग होता है जब प्रजाति की पहचान <b>पूरी तरह पुष्ट न</b> हो।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":46,"local_id":"50046","quid":"Q1000071526","section":"GK","topic":"Economics: 1991 Reforms And Industrial policy","question":{"en":"Which of the following trade policy measure was taken as part of India's liberalisation policy in 1991? [SSC CGL 09/10/26 Shift 2]","hi":"1991 में भारत की उदारीकरण नीति के भाग के रूप में निम्नलिखित में से कौन-सा व्यापार नीति उपाय किया गया? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Trade tariffs were reduced.","hi":"व्यापार शुल्क घटाए गए।"},"2":{"en":"Trade tariffs were increased.","hi":"व्यापार शुल्क बढ़ाए गए।"},"3":{"en":"Exports were reduced.","hi":"निर्यात घटाए गए।"},"4":{"en":"Exports were increased.","hi":"निर्यात बढ़ाए गए।"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Trade tariffs were reduced.</b><br>Trade liberalisation in 1991 <b><u>reduced trade tariffs (customs duties)</u></b>, removed quantitative restrictions and abolished import licensing for most goods.<br><br><br><b><u>Important Points:</u></b><br>• Trade policy reforms aimed at <b>dismantling quantitative restrictions</b> and <b>reducing tariff rates</b>.<br>• Export duties were removed to boost competitiveness.<br>• Increase in exports was an <b>outcome</b>, not a policy measure.","hi":"<b>सही उत्तर: विकल्प (1) – व्यापार शुल्क घटाए गए।</b><br>1991 के व्यापार उदारीकरण में <b><u>व्यापार शुल्क (सीमा शुल्क) घटाए गए</u></b>, मात्रात्मक प्रतिबंध हटाए गए और अधिकांश वस्तुओं के लिए आयात लाइसेंसिंग समाप्त की गई।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• व्यापार नीति सुधारों का उद्देश्य <b>मात्रात्मक प्रतिबंध हटाना</b> और <b>शुल्क दरें घटाना</b> था।<br>• प्रतिस्पर्धात्मकता बढ़ाने के लिए निर्यात शुल्क हटाए गए।<br>• निर्यात में वृद्धि <b>परिणाम</b> था, नीति उपाय नहीं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":47,"local_id":"50047","quid":"Q1000071527","section":"GK","topic":"Static GK: Census","question":{"en":"In the Indian Census process, which operation is carried out before the Population Enumeration phase? [SSC CGL 09/10/26 Shift 2]","hi":"भारतीय जनगणना प्रक्रिया में जनसंख्या गणना चरण से पहले कौन-सा कार्य किया जाता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"House Listing and Housing Census","hi":"मकान सूचीकरण और आवास जनगणना"},"2":{"en":"National Sample and Household Survey","hi":"राष्ट्रीय प्रतिदर्श और परिवार सर्वेक्षण"},"3":{"en":"Socio-Economic and Caste Census","hi":"सामाजिक-आर्थिक और जाति जनगणना"},"4":{"en":"Agricultural and Livestock Census","hi":"कृषि और पशुधन गणना"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – House Listing and Housing Census</b><br>The Indian Census has two phases: <b><u>House Listing and Housing Census</u></b> first, followed by <b>Population Enumeration</b>.<br><br><br><b><u>Important Points:</u></b><br>• Census 2027 house-listing runs <b>April–September 2026</b>; population enumeration in <b>February 2027</b> (reference date 1 March 2027).<br>• Census 2027 is India's first <b>digital census</b> and will include <b>caste enumeration</b>.<br>• Census is conducted under the <b>Census Act, 1948</b> by the Registrar General of India.","hi":"<b>सही उत्तर: विकल्प (1) – मकान सूचीकरण और आवास जनगणना</b><br>भारतीय जनगणना के दो चरण हैं: पहले <b><u>मकान सूचीकरण और आवास जनगणना</u></b>, फिर <b>जनसंख्या गणना</b>।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• जनगणना 2027 का मकान सूचीकरण <b>अप्रैल–सितंबर 2026</b> में; जनसंख्या गणना <b>फरवरी 2027</b> में (संदर्भ तिथि 1 मार्च 2027)।<br>• जनगणना 2027 भारत की पहली <b>डिजिटल जनगणना</b> है और इसमें <b>जाति गणना</b> शामिल होगी।<br>• जनगणना <b>जनगणना अधिनियम, 1948</b> के तहत भारत के महापंजीयक द्वारा की जाती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":48,"local_id":"50048","quid":"Q1000071528","section":"GK","topic":"Static GK: Books and Authors","question":{"en":"Who authored the epic novel A Suitable Boy, regarded as one of the longest works in English literature? [SSC CGL 09/10/26 Shift 2]","hi":"अंग्रेज़ी साहित्य की सबसे लंबी कृतियों में से एक माने जाने वाले महाकाव्यात्मक उपन्यास 'अ सूटेबल बॉय' के लेखक कौन हैं? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Vikram Seth","hi":"विक्रम सेठ"},"2":{"en":"Amitav Ghosh","hi":"अमिताव घोष"},"3":{"en":"Rohinton Mistry","hi":"रोहिंटन मिस्त्री"},"4":{"en":"Shashi Tharoor","hi":"शशि थरूर"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Vikram Seth</b><br><b><u>Vikram Seth</u></b> wrote <b>A Suitable Boy</b> (1993), with about <b>1,349 pages</b> – one of the longest single-volume novels in English.<br><br><br><b><u>Important Points:</u></b><br>• Vikram Seth's other works: <b>The Golden Gate</b> (novel in verse), <b>An Equal Music</b>, <b>Two Lives</b>.<br>• He received the <b>Sahitya Akademi Award (1988)</b> and Padma Shri.<br>• <b>Rohinton Mistry</b> – A Fine Balance; <b>Shashi Tharoor</b> – The Great Indian Novel.","hi":"<b>सही उत्तर: विकल्प (1) – विक्रम सेठ</b><br><b><u>विक्रम सेठ</u></b> ने <b>अ सूटेबल बॉय</b> (1993) लिखा, जिसमें लगभग <b>1,349 पृष्ठ</b> हैं – अंग्रेज़ी के सबसे लंबे एकल-खंड उपन्यासों में से एक।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• विक्रम सेठ की अन्य रचनाएँ: <b>द गोल्डन गेट</b> (पद्य में उपन्यास), <b>ऐन इक्वल म्यूज़िक</b>, <b>टू लाइव्स</b>।<br>• उन्हें <b>साहित्य अकादमी पुरस्कार (1988)</b> और पद्म श्री मिला।<br>• <b>रोहिंटन मिस्त्री</b> – अ फ़ाइन बैलेंस; <b>शशि थरूर</b> – द ग्रेट इंडियन नॉवेल।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":49,"local_id":"50049","quid":"Q1000071529","section":"GK","topic":"Economics: 1991 Reforms And Industrial policy","question":{"en":"Which factor constrained industrial expansion in several sectors following the economic reforms introduced in India in 1991? [SSC CGL 09/10/26 Shift 2]","hi":"1991 में भारत में लागू आर्थिक सुधारों के बाद किस कारक ने कई क्षेत्रों में औद्योगिक विस्तार को सीमित किया? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Excessive growth in export demand","hi":"निर्यात माँग में अत्यधिक वृद्धि"},"2":{"en":"Declining use of foreign technology","hi":"विदेशी प्रौद्योगिकी के उपयोग में गिरावट"},"3":{"en":"Restrictions on private participation","hi":"निजी भागीदारी पर प्रतिबंध"},"4":{"en":"Inadequate investment in infrastructure","hi":"अवसंरचना में अपर्याप्त निवेश"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Inadequate investment in infrastructure</b><br>As per NCERT, industrial growth after 1991 slowed partly because of <b><u>inadequate investment in infrastructure</u></b> (power, transport) along with cheaper imports and decline in demand.<br><br><br><b><u>Important Points:</u></b><br>• Public investment in infrastructure fell due to <b>fiscal tightening</b>.<br>• Agriculture also suffered from reduced public investment in irrigation and power.<br>• Later programmes like the <b>National Infrastructure Pipeline</b> and <b>PM Gati Shakti</b> address this gap.","hi":"<b>सही उत्तर: विकल्प (4) – अवसंरचना में अपर्याप्त निवेश</b><br>NCERT के अनुसार 1991 के बाद औद्योगिक वृद्धि आंशिक रूप से <b><u>अवसंरचना में अपर्याप्त निवेश</u></b> (बिजली, परिवहन) के साथ-साथ सस्ते आयात और माँग में गिरावट के कारण धीमी हुई।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>राजकोषीय सख्ती</b> के कारण अवसंरचना में सार्वजनिक निवेश घटा।<br>• सिंचाई और बिजली में घटे सार्वजनिक निवेश से कृषि भी प्रभावित हुई।<br>• बाद के कार्यक्रम जैसे <b>राष्ट्रीय अवसंरचना पाइपलाइन</b> और <b>पीएम गति शक्ति</b> इस कमी को दूर करते हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":50,"local_id":"50050","quid":"Q1000071530","section":"GK","topic":"Physics: Miscellaneous","question":{"en":"Why is the first-order Stark energy correction zero for the nondegenerate hydrogen (1s) ground state in a uniform external electric field? [SSC CGL 09/10/26 Shift 2]","hi":"एकसमान बाह्य विद्युत क्षेत्र में अपभ्रष्ट-रहित हाइड्रोजन (1s) मूल अवस्था के लिए प्रथम-कोटि स्टार्क ऊर्जा संशोधन शून्य क्यों होता है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Because the electric field does not interact with bound electrons","hi":"क्योंकि विद्युत क्षेत्र बद्ध इलेक्ट्रॉनों से अन्योन्यक्रिया नहीं करता"},"2":{"en":"Because the ground-state wavefunction is rotationally symmetric","hi":"क्योंकि मूल अवस्था का तरंग फलन घूर्णीय रूप से सममित है"},"3":{"en":"Because the perturbation commutes with the hydrogen Hamiltonian","hi":"क्योंकि विक्षोभ हाइड्रोजन हैमिल्टोनियन के साथ क्रमविनिमेय है"},"4":{"en":"Because all excited states are energetically degenerate with the ground state","hi":"क्योंकि सभी उत्तेजित अवस्थाएँ मूल अवस्था के साथ ऊर्जा में अपभ्रष्ट हैं"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Because the ground-state wavefunction is rotationally symmetric</b><br>The first-order correction is \\(\\langle 1s|eEz|1s\\rangle\\). The 1s wavefunction is <b><u>spherically (rotationally) symmetric</u></b> with even parity, while z is odd, so the integral is zero; the ground state has <b>no permanent dipole moment</b>.<br><br><br><b><u>Important Points:</u></b><br>• The ground state shows only a <b>second-order (quadratic) Stark effect</b>, proportional to E².<br>• The <b>n = 2</b> level of hydrogen is degenerate and shows a <b>linear Stark effect</b>.<br>• The Stark effect (1913) is the splitting of spectral lines in an electric field; in a magnetic field it is the <b>Zeeman effect</b>.","hi":"<b>सही उत्तर: विकल्प (2) – क्योंकि मूल अवस्था का तरंग फलन घूर्णीय रूप से सममित है</b><br>प्रथम-कोटि संशोधन \\(\\langle 1s|eEz|1s\\rangle\\) है। 1s तरंग फलन <b><u>गोलीय (घूर्णीय) रूप से सममित</u></b> और सम समता वाला है, जबकि z विषम है, अतः समाकल शून्य होता है; मूल अवस्था में <b>कोई स्थायी द्विध्रुव आघूर्ण नहीं</b> होता।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मूल अवस्था केवल <b>द्वितीय-कोटि (द्विघाती) स्टार्क प्रभाव</b> दिखाती है, जो E² के समानुपाती है।<br>• हाइड्रोजन का <b>n = 2</b> स्तर अपभ्रष्ट है और <b>रैखिक स्टार्क प्रभाव</b> दिखाता है।<br>• स्टार्क प्रभाव (1913) विद्युत क्षेत्र में वर्णक्रमीय रेखाओं का विभाजन है; चुंबकीय क्षेत्र में यह <b>ज़ीमान प्रभाव</b> है।"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"MATH":{"seconds":900,"questions":[{"no":51,"local_id":"50051","quid":"Q1000071531","section":"MATH","topic":"Mensuration (3D)","question":{"en":"The base of a right prism is a triangle with area 24 cm². Prism height is 10 cm. Volume? [SSC CGL 09/10/26 Shift 2]","hi":"एक लंब प्रिज़्म का आधार 24 cm² क्षेत्रफल वाला त्रिभुज है। प्रिज़्म की ऊँचाई 10 cm है। आयतन? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"220 cm³"},"2":{"en":"240 cm³"},"3":{"en":"260 cm³"},"4":{"en":"280 cm³"}},"answer":"2","solution":{"en":"\\(V = \\) base area \\(\\times\\) height<br>\\(= 24 \\times 10\\)<br>\\(= \\boxed{240\\ \\text{cm}^3}\\)<br><br><b>Hence, the correct answer is option (2): 240 cm³.</b>","hi":"\\(V = \\) आधार क्षेत्रफल \\(\\times\\) ऊँचाई<br>\\(= 24 \\times 10\\)<br>\\(= \\boxed{240\\ \\text{cm}^3}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 240 cm³ है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":52,"local_id":"50052","quid":"Q1000071532","section":"MATH","topic":"Mensuration (2D)","question":{"en":"If the semi-perimeter of a triangle is 24 cm and the lengths of two sides are 18 cm and 16 cm, what is the length of the third side? [SSC CGL 09/10/26 Shift 2]","hi":"यदि एक त्रिभुज का अर्धपरिमाप 24 cm है और दो भुजाओं की लंबाई 18 cm तथा 16 cm है, तो तीसरी भुजा की लंबाई क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"16 cm"},"2":{"en":"20 cm"},"3":{"en":"14 cm"},"4":{"en":"18 cm"}},"answer":"3","solution":{"en":"Perimeter \\(= 2 \\times 24 = 48\\) cm<br>Third side \\(= 48 - (18 + 16)\\)<br>\\(= \\boxed{14\\ \\text{cm}}\\)<br><br><b>Hence, the correct answer is option (3): 14 cm.</b>","hi":"परिमाप \\(= 2 \\times 24 = 48\\) cm<br>तीसरी भुजा \\(= 48 - (18 + 16)\\)<br>\\(= \\boxed{14\\ \\text{cm}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 14 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":53,"local_id":"50053","quid":"Q1000071533","section":"MATH","topic":"Mensuration (3D)","question":{"en":"A closed cylindrical tank has radius 5 m and height 8 m. What is its total surface area? [SSC CGL 09/10/26 Shift 2]","hi":"एक बंद बेलनाकार टंकी की त्रिज्या 5 m और ऊँचाई 8 m है। उसका कुल पृष्ठीय क्षेत्रफल क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"440π m²"},"2":{"en":"130π m²"},"3":{"en":"1300π m²"},"4":{"en":"130 m²"}},"answer":"2","solution":{"en":"\\(TSA = 2\\pi r(r + h)\\)<br>\\(= 2\\pi (5)(13)\\)<br>\\(= \\boxed{130\\pi\\ \\text{m}^2}\\)<br><br><b>Hence, the correct answer is option (2): 130π m².</b>","hi":"\\(TSA = 2\\pi r(r + h)\\)<br>\\(= 2\\pi (5)(13)\\)<br>\\(= \\boxed{130\\pi\\ \\text{m}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 130π m² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":54,"local_id":"50054","quid":"Q1000071534","section":"MATH","topic":"Partnership","question":{"en":"P and Q started their business by investing ₹16,000 and ₹15,000, respectively. After 3 months, P withdrew ₹5,000 from his investment, whereas Q invested another ₹5,000 in his investment. After another 3 months, C joined the business by investing ₹21,000. Calculate the share of C out of the annual profit of ₹24,900. [SSC CGL 09/10/26 Shift 2]","hi":"P और Q ने क्रमशः ₹16,000 और ₹15,000 निवेश करके व्यवसाय शुरू किया। 3 माह बाद P ने अपने निवेश से ₹5,000 निकाल लिए, जबकि Q ने अपने निवेश में ₹5,000 और लगाए। अगले 3 माह बाद C ने ₹21,000 निवेश करके व्यवसाय में प्रवेश किया। ₹24,900 के वार्षिक लाभ में से C का हिस्सा ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"₹5,600"},"2":{"en":"₹6,300"},"3":{"en":"₹7,200"},"4":{"en":"₹8,100"}},"answer":"2","solution":{"en":"P \\(= 16000 \\times 3 + 11000 \\times 9 = 147000\\)<br>Q \\(= 15000 \\times 3 + 20000 \\times 9 = 225000\\)<br>C \\(= 21000 \\times 6 = 126000\\)<br>Ratio \\(= 147 : 225 : 126\\); C's share \\(= \\frac{126}{498} \\times 24900 = \\boxed{6{,}300}\\)<br><br><b>Hence, the correct answer is option (2): ₹6,300.</b>","hi":"P \\(= 16000 \\times 3 + 11000 \\times 9 = 147000\\)<br>Q \\(= 15000 \\times 3 + 20000 \\times 9 = 225000\\)<br>C \\(= 21000 \\times 6 = 126000\\)<br>अनुपात \\(= 147 : 225 : 126\\); C का हिस्सा \\(= \\frac{126}{498} \\times 24900 = \\boxed{6{,}300}\\)<br><br><b>अतः सही उत्तर विकल्प (2): ₹6,300 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":55,"local_id":"50055","quid":"Q1000071535","section":"MATH","topic":"Average","question":{"en":"A man spends ₹1800 per month on average for the first four months and ₹2000 per month for the next eight months. If he saves ₹5600 in a year, find his average monthly income. [SSC CGL 09/10/26 Shift 2]","hi":"एक व्यक्ति पहले चार महीनों में औसतन ₹1800 प्रति माह और अगले आठ महीनों में ₹2000 प्रति माह खर्च करता है। यदि वह एक वर्ष में ₹5600 बचाता है, तो उसकी औसत मासिक आय ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"₹1200"},"2":{"en":"₹4500"},"3":{"en":"₹6500"},"4":{"en":"₹2400"}},"answer":"4","solution":{"en":"Yearly expenditure \\(= 1800 \\times 4 + 2000 \\times 8 = 23200\\)<br>Income \\(= 23200 + 5600 = 28800\\)<br>Average \\(= \\frac{28800}{12} = \\boxed{2400}\\)<br><br><b>Hence, the correct answer is option (4): ₹2400.</b>","hi":"वार्षिक व्यय \\(= 1800 \\times 4 + 2000 \\times 8 = 23200\\)<br>आय \\(= 23200 + 5600 = 28800\\)<br>औसत \\(= \\frac{28800}{12} = \\boxed{2400}\\)<br><br><b>अतः सही उत्तर विकल्प (4): ₹2400 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":56,"local_id":"50056","quid":"Q1000071536","section":"MATH","topic":"Compound Interest (CI)","question":{"en":"A sum of ₹2,500 amounts to ₹2,916 in 2 years at compound interest. Calculate the rate of interest. [SSC CGL 09/10/26 Shift 2]","hi":"₹2,500 की राशि चक्रवृद्धि ब्याज पर 2 वर्ष में ₹2,916 हो जाती है। ब्याज दर ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"15%"},"2":{"en":"8%"},"3":{"en":"12%"},"4":{"en":"6%"}},"answer":"2","solution":{"en":"\\(2500(1 + r)^2 = 2916\\)<br>\\((1 + r)^2 = 1.1664 \\Rightarrow 1 + r = 1.08\\)<br>\\(r = \\boxed{8\\%}\\)<br><br><b>Hence, the correct answer is option (2): 8%.</b>","hi":"\\(2500(1 + r)^2 = 2916\\)<br>\\((1 + r)^2 = 1.1664 \\Rightarrow 1 + r = 1.08\\)<br>\\(r = \\boxed{8\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 8% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":57,"local_id":"50057","quid":"Q1000071537","section":"MATH","topic":"Mensuration (2D)","question":{"en":"A regular hexagon and a square have the same perimeter. If the area of the square is 144 cm², find the exact area of the hexagon. [SSC CGL 09/10/26 Shift 2]","hi":"एक सम षट्भुज और एक वर्ग का परिमाप समान है। यदि वर्ग का क्षेत्रफल 144 cm² है, तो षट्भुज का ठीक क्षेत्रफल ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"\\(96\\sqrt{3}\\) cm²"},"2":{"en":"\\(49\\sqrt{3}\\) cm²"},"3":{"en":"\\(26\\sqrt{3}\\) cm²"},"4":{"en":"\\(87\\sqrt{3}\\) cm²"}},"answer":"1","solution":{"en":"Square side \\(= 12\\), perimeter \\(= 48\\)<br>Hexagon side \\(= 8\\); area \\(= \\frac{3\\sqrt{3}}{2}a^2 = \\frac{3\\sqrt{3}}{2} \\times 64\\)<br>\\(= \\boxed{96\\sqrt{3}\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (1): \\(96\\sqrt{3}\\) cm².</b>","hi":"वर्ग की भुजा \\(= 12\\), परिमाप \\(= 48\\)<br>षट्भुज की भुजा \\(= 8\\); क्षेत्रफल \\(= \\frac{3\\sqrt{3}}{2}a^2 = \\frac{3\\sqrt{3}}{2} \\times 64\\)<br>\\(= \\boxed{96\\sqrt{3}\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (1): \\(96\\sqrt{3}\\) cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":58,"local_id":"50058","quid":"Q1000071538","section":"MATH","topic":"Mensuration (2D)","question":{"en":"The ratio of the areas of two concentric circles is 16: 9. If the difference between their radii is 14 m, find the radius of the larger circle. [SSC CGL 09/10/26 Shift 2]","hi":"दो संकेंद्री वृत्तों के क्षेत्रफलों का अनुपात 16: 9 है। यदि उनकी त्रिज्याओं का अंतर 14 m है, तो बड़े वृत्त की त्रिज्या ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"56 m"},"2":{"en":"64 m"},"3":{"en":"42 m"},"4":{"en":"38 m"}},"answer":"1","solution":{"en":"Radii are in the ratio \\(\\sqrt{16} : \\sqrt{9} = 4 : 3\\)<br>\\(4k - 3k = 14 \\Rightarrow k = 14\\)<br>Larger radius \\(= \\boxed{56\\ \\text{m}}\\)<br><br><b>Hence, the correct answer is option (1): 56 m.</b>","hi":"त्रिज्याएँ \\(\\sqrt{16} : \\sqrt{9} = 4 : 3\\) के अनुपात में हैं<br>\\(4k - 3k = 14 \\Rightarrow k = 14\\)<br>बड़ी त्रिज्या \\(= \\boxed{56\\ \\text{m}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 56 m है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":59,"local_id":"50059","quid":"Q1000071539","section":"MATH","topic":"Mensuration (3D)","question":{"en":"The height of a right circular cone is 7 cm and its slant height is 25 cm. Find its curved surface area. [SSC CGL 09/10/26 Shift 2]","hi":"एक लंब वृत्तीय शंकु की ऊँचाई 7 cm और तिर्यक ऊँचाई 25 cm है। उसका वक्र पृष्ठीय क्षेत्रफल ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"720π cm²"},"2":{"en":"650π cm²"},"3":{"en":"600π cm²"},"4":{"en":"700π cm²"}},"answer":"3","solution":{"en":"\\(r = \\sqrt{25^2 - 7^2} = 24\\) cm<br>\\(CSA = \\pi r l = \\pi (24)(25)\\)<br>\\(= \\boxed{600\\pi\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (3): 600π cm².</b>","hi":"\\(r = \\sqrt{25^2 - 7^2} = 24\\) cm<br>\\(CSA = \\pi r l = \\pi (24)(25)\\)<br>\\(= \\boxed{600\\pi\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 600π cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":60,"local_id":"50060","quid":"Q1000071540","section":"MATH","topic":"Height and Distance","question":{"en":"A ladder of length 14 m rests against a wall making an angle of 45° with the ground. Find the distance of the foot from the wall. [SSC CGL 09/10/26 Shift 2]","hi":"14 m लंबी एक सीढ़ी भूमि से 45° का कोण बनाते हुए दीवार के सहारे टिकी है। सीढ़ी के तल का दीवार से अंतर ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"10.1 m"},"2":{"en":"7.8 m"},"3":{"en":"9.9 m"},"4":{"en":"8.9 m"}},"answer":"3","solution":{"en":"\\(\\cos 45° = \\frac{d}{14}\\)<br>\\(d = 14 \\times \\frac{1}{\\sqrt{2}} = 9.899\\)<br>\\(\\approx \\boxed{9.9\\ \\text{m}}\\)<br><br><b>Hence, the correct answer is option (3): 9.9 m.</b>","hi":"\\(\\cos 45° = \\frac{d}{14}\\)<br>\\(d = 14 \\times \\frac{1}{\\sqrt{2}} = 9.899\\)<br>\\(\\approx \\boxed{9.9\\ \\text{m}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 9.9 m है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":61,"local_id":"50061","quid":"Q1000071541","section":"MATH","topic":"Geometry","question":{"en":"AB is a chord of a circle and P lies on the minor arc AB. Tangents at A and B meet at point T. If ∠APB = 104°, find ∠ATB. [SSC CGL 09/10/26 Shift 2]","hi":"AB एक वृत्त की जीवा है और P लघु चाप AB पर स्थित है। A और B पर स्पर्श रेखाएँ बिंदु T पर मिलती हैं। यदि ∠APB = 104° है, तो ∠ATB ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"28°"},"2":{"en":"36°"},"3":{"en":"48°"},"4":{"en":"54°"}},"answer":"1","solution":{"en":"P is on the minor arc, so the angle on the major arc \\(= 180° - 104° = 76°\\)<br>Central angle \\(\\angle AOB = 2 \\times 76° = 152°\\)<br>\\(\\angle ATB = 180° - 152° = \\boxed{28°}\\)<br><br><b>Hence, the correct answer is option (1): 28°.</b>","hi":"P लघु चाप पर है, अतः दीर्घ चाप पर बना कोण \\(= 180° - 104° = 76°\\)<br>केंद्रीय कोण \\(\\angle AOB = 2 \\times 76° = 152°\\)<br>\\(\\angle ATB = 180° - 152° = \\boxed{28°}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 28° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":62,"local_id":"50062","quid":"Q1000071542","section":"MATH","topic":"Trigonometry","question":{"en":"If secθ + tanθ = 5, find the value of sinθ. [SSC CGL 09/10/26 Shift 2]","hi":"यदि secθ + tanθ = 5 है, तो sinθ का मान ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{13}{12}\\)"},"2":{"en":"\\(\\frac{5}{12}\\)"},"3":{"en":"\\(\\frac{12}{13}\\)"},"4":{"en":"\\(\\frac{12}{5}\\)"}},"answer":"3","solution":{"en":"\\(\\sin\\theta = \\frac{k^2 - 1}{k^2 + 1}\\) with \\(k = 5\\)<br>\\(= \\frac{25 - 1}{25 + 1} = \\frac{24}{26}\\)<br>\\(= \\boxed{\\frac{12}{13}}\\)<br><br><b>Hence, the correct answer is option (3): \\(\\frac{12}{13}\\).</b>","hi":"\\(\\sin\\theta = \\frac{k^2 - 1}{k^2 + 1}\\), जहाँ \\(k = 5\\)<br>\\(= \\frac{25 - 1}{25 + 1} = \\frac{24}{26}\\)<br>\\(= \\boxed{\\frac{12}{13}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): \\(\\frac{12}{13}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":63,"local_id":"50063","quid":"Q1000071543","section":"MATH","topic":"Algebra","question":{"en":"If x = \\(\\sqrt{\\frac{2+\\sqrt{3}}{2-\\sqrt{3}}}\\) then what is the value of x² + x − 9? [SSC CGL 09/10/26 Shift 2]","hi":"यदि x = \\(\\sqrt{\\frac{2+\\sqrt{3}}{2-\\sqrt{3}}}\\) है, तो x² + x − 9 का मान क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"\\(5\\sqrt{3}\\)"},"2":{"en":"\\(5\\sqrt{2}\\)"},"3":{"en":"0"},"4":{"en":"1"}},"answer":"1","solution":{"en":"\\(\\frac{2+\\sqrt{3}}{2-\\sqrt{3}} = (2+\\sqrt{3})^2 \\Rightarrow x = 2 + \\sqrt{3}\\)<br>\\(x^2 = 7 + 4\\sqrt{3}\\)<br>\\(x^2 + x - 9 = (7 + 4\\sqrt{3}) + (2 + \\sqrt{3}) - 9 = \\boxed{5\\sqrt{3}}\\)<br><br><b>Hence, the correct answer is option (1): \\(5\\sqrt{3}\\).</b>","hi":"\\(\\frac{2+\\sqrt{3}}{2-\\sqrt{3}} = (2+\\sqrt{3})^2 \\Rightarrow x = 2 + \\sqrt{3}\\)<br>\\(x^2 = 7 + 4\\sqrt{3}\\)<br>\\(x^2 + x - 9 = (7 + 4\\sqrt{3}) + (2 + \\sqrt{3}) - 9 = \\boxed{5\\sqrt{3}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): \\(5\\sqrt{3}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":64,"local_id":"50064","quid":"Q1000071544","section":"MATH","topic":"Algebra","question":{"en":"If x + \\(\\frac{1}{x} = \\sqrt{17}\\), then find the value of \\(\\frac{x^4 - 1}{x^2}\\). [SSC CGL 09/10/26 Shift 2]","hi":"यदि x + \\(\\frac{1}{x} = \\sqrt{17}\\) है, तो \\(\\frac{x^4 - 1}{x^2}\\) का मान ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\pm\\sqrt{221}\\)"},"2":{"en":"\\(\\pm\\sqrt{223}\\)"},"3":{"en":"\\(\\pm\\sqrt{119}\\)"},"4":{"en":"\\(\\pm\\sqrt{116}\\)"}},"answer":"1","solution":{"en":"\\(\\frac{x^4 - 1}{x^2} = x^2 - \\frac{1}{x^2} = \\left(x + \\frac{1}{x}\\right)\\left(x - \\frac{1}{x}\\right)\\)<br>\\(\\left(x - \\frac{1}{x}\\right)^2 = 17 - 4 = 13 \\Rightarrow x - \\frac{1}{x} = \\pm\\sqrt{13}\\)<br>\\(= \\pm\\sqrt{17} \\times \\sqrt{13} = \\boxed{\\pm\\sqrt{221}}\\)<br><br><b>Hence, the correct answer is option (1): \\(\\pm\\sqrt{221}\\).</b>","hi":"\\(\\frac{x^4 - 1}{x^2} = x^2 - \\frac{1}{x^2} = \\left(x + \\frac{1}{x}\\right)\\left(x - \\frac{1}{x}\\right)\\)<br>\\(\\left(x - \\frac{1}{x}\\right)^2 = 17 - 4 = 13 \\Rightarrow x - \\frac{1}{x} = \\pm\\sqrt{13}\\)<br>\\(= \\pm\\sqrt{17} \\times \\sqrt{13} = \\boxed{\\pm\\sqrt{221}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): \\(\\pm\\sqrt{221}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":65,"local_id":"50065","quid":"Q1000071545","section":"MATH","topic":"Mensuration (3D)","question":{"en":"If a sphere of radius r causes a water level rise of h in a cylinder of radius R, what is the relationship between r, R, and h? [SSC CGL 09/10/26 Shift 2]","hi":"यदि r त्रिज्या का एक गोला R त्रिज्या के बेलन में पानी के स्तर में h की वृद्धि करता है, तो r, R और h के बीच क्या संबंध है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{4}{3}r^3 = R^2h\\)"},"2":{"en":"\\(r^3 = R^2h\\)"},"3":{"en":"\\(\\frac{2}{3}r^3 = 2R^2h\\)"},"4":{"en":"\\(r^3 = 4R^2h\\)"}},"answer":"1","solution":{"en":"Volume of sphere = volume of water displaced<br>\\(\\frac{4}{3}\\pi r^3 = \\pi R^2 h\\)<br>\\(\\boxed{\\frac{4}{3}r^3 = R^2h}\\)<br><br><b>Hence, the correct answer is option (1): \\(\\frac{4}{3}r^3 = R^2h\\).</b>","hi":"गोले का आयतन = विस्थापित पानी का आयतन<br>\\(\\frac{4}{3}\\pi r^3 = \\pi R^2 h\\)<br>\\(\\boxed{\\frac{4}{3}r^3 = R^2h}\\)<br><br><b>अतः सही उत्तर विकल्प (1): \\(\\frac{4}{3}r^3 = R^2h\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":66,"local_id":"50066","quid":"Q1000071546","section":"MATH","topic":"Geometry","question":{"en":"In △ABC, D and E are the points on AB and AC, respectively, such that AD × AC = AB × AE. If ∠ADE = ∠ACB + 30° and ∠ABC = 78°, find the measure of angle A. [SSC CGL 09/10/26 Shift 2]","hi":"△ABC में, D और E क्रमशः AB और AC पर ऐसे बिंदु हैं कि AD × AC = AB × AE है। यदि ∠ADE = ∠ACB + 30° और ∠ABC = 78° है, तो कोण A का माप ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"48°"},"2":{"en":"68°"},"3":{"en":"60°"},"4":{"en":"54°"}},"answer":"4","solution":{"en":"\\(\\frac{AD}{AB} = \\frac{AE}{AC}\\) with common \\(\\angle A \\Rightarrow \\triangle ADE \\sim \\triangle ABC\\)<br>So \\(\\angle ADE = \\angle ABC = 78°\\)<br>\\(\\angle ACB = 78° - 30° = 48°\\)<br>\\(\\angle A = 180° - 78° - 48° = \\boxed{54°}\\)<br><br><b>Hence, the correct answer is option (4): 54°.</b>","hi":"\\(\\frac{AD}{AB} = \\frac{AE}{AC}\\) और उभयनिष्ठ \\(\\angle A \\Rightarrow \\triangle ADE \\sim \\triangle ABC\\)<br>अतः \\(\\angle ADE = \\angle ABC = 78°\\)<br>\\(\\angle ACB = 78° - 30° = 48°\\)<br>\\(\\angle A = 180° - 78° - 48° = \\boxed{54°}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 54° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":67,"local_id":"50067","quid":"Q1000071547","section":"MATH","topic":"Percentage","question":{"en":"To control a localized food crisis, a government mandates an anti-hoarding policy that artificially forces down the wholesale price of rice by 15%. A commercial wholesaler wants to ensure that their total daily sales revenue increases by exactly 2% despite this price cut. By what percentage must the wholesaler increase the volume of rice they sell each day? [SSC CGL 09/10/26 Shift 2]","hi":"स्थानीय खाद्य संकट नियंत्रित करने के लिए सरकार एक जमाखोरी-विरोधी नीति लागू करती है जो चावल के थोक मूल्य को कृपया 15% घटा देती है। एक वाणिज्यिक थोक विक्रेता चाहता है कि इस मूल्य कटौती के बावजूद उसका कुल दैनिक बिक्री राजस्व ठीक 2% बढ़े। उसे प्रतिदिन बेची जाने वाली चावल की मात्रा में कितने प्रतिशत वृद्धि करनी चाहिए? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"17%"},"2":{"en":"13%"},"3":{"en":"20%"},"4":{"en":"19%"}},"answer":"3","solution":{"en":"Revenue \\(= \\) price \\(\\times\\) quantity<br>\\(0.85 \\times (1 + x) = 1.02 \\Rightarrow 1 + x = 1.2\\)<br>\\(x = \\boxed{20\\%}\\)<br><br><b>Hence, the correct answer is option (3): 20%.</b>","hi":"राजस्व \\(= \\) मूल्य \\(\\times\\) मात्रा<br>\\(0.85 \\times (1 + x) = 1.02 \\Rightarrow 1 + x = 1.2\\)<br>\\(x = \\boxed{20\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 20% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":68,"local_id":"50068","quid":"Q1000071548","section":"MATH","topic":"Ratio and Proportion","question":{"en":"In an examination, the ratio of the number of students who passed the examination to those who couldn't pass is 25:4. If 5 more students had appeared and the number of students who couldn't pass had been 2 less than the original number, the ratio of passed students to failed students would have been 22:3. Find the total number of students who originally appeared for the examination. [SSC CGL 09/10/26 Shift 2]","hi":"एक परीक्षा में उत्तीर्ण छात्रों की संख्या और अनुत्तीर्ण छात्रों की संख्या का अनुपात 25:4 है। यदि 5 अधिक छात्र परीक्षा में बैठे होते और अनुत्तीर्ण छात्रों की संख्या मूल संख्या से 2 कम होती, तो उत्तीर्ण और अनुत्तीर्ण छात्रों का अनुपात 22:3 होता। परीक्षा में मूल रूप से बैठे छात्रों की कुल संख्या ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"87"},"2":{"en":"116"},"3":{"en":"145"},"4":{"en":"174"}},"answer":"3","solution":{"en":"Let passed \\(= 25x\\), failed \\(= 4x\\)<br>New: total \\(= 29x + 5\\), failed \\(= 4x - 2\\), passed \\(= 25x + 7\\)<br>\\(\\frac{25x + 7}{4x - 2} = \\frac{22}{3} \\Rightarrow 75x + 21 = 88x - 44 \\Rightarrow x = 5\\)<br>Total \\(= 29 \\times 5 = \\boxed{145}\\)<br><br><b>Hence, the correct answer is option (3): 145.</b>","hi":"मान लीजिए उत्तीर्ण \\(= 25x\\), अनुत्तीर्ण \\(= 4x\\)<br>नई स्थिति: कुल \\(= 29x + 5\\), अनुत्तीर्ण \\(= 4x - 2\\), उत्तीर्ण \\(= 25x + 7\\)<br>\\(\\frac{25x + 7}{4x - 2} = \\frac{22}{3} \\Rightarrow 75x + 21 = 88x - 44 \\Rightarrow x = 5\\)<br>कुल \\(= 29 \\times 5 = \\boxed{145}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 145 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":69,"local_id":"50069","quid":"Q1000071549","section":"MATH","topic":"Time and Work","question":{"en":"Preeti and Avantika are two sisters who have been asked by their mother to properly arrange their closet. The two sisters can together complete arranging it in 6 days. However, if Preeti works with 25% less efficiency and Avantika works with 20% more efficiency than their respective usual efficiencies, the work is seen to be completed in \\(\\frac{200}{31}\\) days. Find the time that will be taken by Preeti to arrange the entire closet alone. [SSC CGL 09/10/26 Shift 2]","hi":"प्रीति और अवंतिका दो बहनें हैं जिन्हें उनकी माँ ने अपनी अलमारी ठीक से व्यवस्थित करने को कहा है। दोनों बहनें मिलकर इसे 6 दिनों में पूरा कर सकती हैं। परंतु यदि प्रीति अपनी सामान्य क्षमता से 25% कम क्षमता से और अवंतिका 20% अधिक क्षमता से काम करे, तो कार्य \\(\\frac{200}{31}\\) दिनों में पूरा होता है। पूरी अलमारी अकेले व्यवस्थित करने में प्रीति को कितना समय लगेगा? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"12 days","hi":"12 दिन"},"2":{"en":"11 days","hi":"11 दिन"},"3":{"en":"10 days","hi":"10 दिन"},"4":{"en":"9 days","hi":"9 दिन"}},"answer":"3","solution":{"en":"\\(p + a = \\frac{1}{6}\\); also \\(0.75p + 1.2a = \\frac{31}{200}\\)<br>\\(0.75p + 1.2\\left(\\frac{1}{6} - p\\right) = 0.155 \\Rightarrow 0.45p = 0.045\\)<br>\\(p = \\frac{1}{10} \\Rightarrow \\boxed{10\\ \\text{days}}\\)<br><br><b>Hence, the correct answer is option (3): 10 days.</b>","hi":"\\(p + a = \\frac{1}{6}\\); साथ ही \\(0.75p + 1.2a = \\frac{31}{200}\\)<br>\\(0.75p + 1.2\\left(\\frac{1}{6} - p\\right) = 0.155 \\Rightarrow 0.45p = 0.045\\)<br>\\(p = \\frac{1}{10} \\Rightarrow \\boxed{10\\ \\text{दिन}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 10 दिन है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":70,"local_id":"50070","quid":"Q1000071550","section":"MATH","topic":"Trigonometry","question":{"en":"In a right triangle ABC with ∠C = 90°, if sin A = 0.6, find tan B. [SSC CGL 09/10/26 Shift 2]","hi":"समकोण त्रिभुज ABC में जहाँ ∠C = 90° है, यदि sin A = 0.6 है, तो tan B ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\frac{5}{4}\\)"},"2":{"en":"\\(\\frac{3}{4}\\)"},"3":{"en":"\\(\\frac{4}{3}\\)"},"4":{"en":"\\(\\frac{5}{3}\\)"}},"answer":"3","solution":{"en":"\\(\\sin A = \\frac{3}{5} \\Rightarrow BC : CA : AB = 3 : 4 : 5\\)<br>\\(\\tan B = \\frac{AC}{BC}\\)<br>\\(= \\boxed{\\frac{4}{3}}\\)<br><br><b>Hence, the correct answer is option (3): \\(\\frac{4}{3}\\).</b>","hi":"\\(\\sin A = \\frac{3}{5} \\Rightarrow BC : CA : AB = 3 : 4 : 5\\)<br>\\(\\tan B = \\frac{AC}{BC}\\)<br>\\(= \\boxed{\\frac{4}{3}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): \\(\\frac{4}{3}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":71,"local_id":"50071","quid":"Q1000071551","section":"MATH","topic":"Trigonometry","question":{"en":"Simplify: sin²(90°−θ) + sin²θ [SSC CGL 09/10/26 Shift 2]","hi":"सरल कीजिए: sin²(90°−θ) + sin²θ [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"1"},"2":{"en":"sin²θ"},"3":{"en":"cos²θ"},"4":{"en":"0"}},"answer":"1","solution":{"en":"\\(\\sin(90° - \\theta) = \\cos\\theta\\)<br>\\(\\cos^2\\theta + \\sin^2\\theta\\)<br>\\(= \\boxed{1}\\)<br><br><b>Hence, the correct answer is option (1): 1.</b>","hi":"\\(\\sin(90° - \\theta) = \\cos\\theta\\)<br>\\(\\cos^2\\theta + \\sin^2\\theta\\)<br>\\(= \\boxed{1}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 1 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":72,"local_id":"50072","quid":"Q1000071552","section":"MATH","topic":"Algebra","question":{"en":"If u + v = 17 and uv = 39, find the value of u² + v². [SSC CGL 09/10/26 Shift 2]","hi":"यदि u + v = 17 और uv = 39 है, तो u² + v² का मान ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"207"},"2":{"en":"209"},"3":{"en":"211"},"4":{"en":"213"}},"answer":"3","solution":{"en":"\\(u^2 + v^2 = (u + v)^2 - 2uv\\)<br>\\(= 289 - 78\\)<br>\\(= \\boxed{211}\\)<br><br><b>Hence, the correct answer is option (3): 211.</b>","hi":"\\(u^2 + v^2 = (u + v)^2 - 2uv\\)<br>\\(= 289 - 78\\)<br>\\(= \\boxed{211}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 211 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":73,"local_id":"50073","quid":"Q1000071553","section":"MATH","topic":"Algebra","question":{"en":"If x + \\(\\frac{1}{x} = 12\\), then find the value of \\(x^4 + \\frac{1}{x^4} + x^2 + \\frac{1}{x^2}\\). [SSC CGL 09/10/26 Shift 2]","hi":"यदि x + \\(\\frac{1}{x} = 12\\) है, तो \\(x^4 + \\frac{1}{x^4} + x^2 + \\frac{1}{x^2}\\) का मान ज्ञात कीजिए। [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"20306"},"2":{"en":"20304"},"3":{"en":"20162"},"4":{"en":"20448"}},"answer":"2","solution":{"en":"\\(x^2 + \\frac{1}{x^2} = 144 - 2 = 142\\)<br>\\(x^4 + \\frac{1}{x^4} = 142^2 - 2 = 20162\\)<br>Sum \\(= 20162 + 142 = \\boxed{20304}\\)<br><br><b>Hence, the correct answer is option (2): 20304.</b>","hi":"\\(x^2 + \\frac{1}{x^2} = 144 - 2 = 142\\)<br>\\(x^4 + \\frac{1}{x^4} = 142^2 - 2 = 20162\\)<br>योग \\(= 20162 + 142 = \\boxed{20304}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 20304 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":74,"local_id":"50074","quid":"Q1000071554","section":"MATH","topic":"Mixture and Alligation","question":{"en":"A vessel contains 500 litres of an aqueous solution with a 24% salt concentration by volume. The following sequential operations are performed:<br>• 100 litres of the solution is removed and replaced with an equal volume of pure water.<br>• 50 litres of this newly formed solution is removed and replaced with an equal volume of a 60% salt solution.<br>What is the final percentage of salt by volume in the resulting mixture? [SSC CGL 09/10/26 Shift 2]","hi":"एक बर्तन में 500 लीटर जलीय घोल है जिसमें आयतन के अनुसार 24% नमक की सांद्रता है। निम्नलिखित क्रमिक क्रियाएँ की जाती हैं:<br>• 100 लीटर घोल निकालकर उसके बराबर आयतन का शुद्ध पानी डाला जाता है।<br>• इस नए बने घोल का 50 लीटर निकालकर उसके बराबर आयतन का 60% नमक का घोल डाला जाता है।<br>परिणामी मिश्रण में आयतन के अनुसार नमक का अंतिम प्रतिशत क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"19.20%"},"2":{"en":"21.12%"},"3":{"en":"23.28%"},"4":{"en":"25.20%"}},"answer":"3","solution":{"en":"Initial salt \\(= 24\\%\\) of 500 \\(= 120\\) L<br>After first step: salt \\(= 120 - 24 = 96\\) L in 500 L<br>After second step: salt \\(= 96 - \\frac{96 \\times 50}{500} + 30 = 116.4\\) L<br>\\(\\frac{116.4}{500} \\times 100 = \\boxed{23.28\\%}\\)<br><br><b>Hence, the correct answer is option (3): 23.28%.</b>","hi":"प्रारंभिक नमक \\(= 500\\) का 24% \\(= 120\\) लीटर<br>पहली क्रिया के बाद: 500 लीटर में नमक \\(= 120 - 24 = 96\\) लीटर<br>दूसरी क्रिया के बाद: नमक \\(= 96 - \\frac{96 \\times 50}{500} + 30 = 116.4\\) लीटर<br>\\(\\frac{116.4}{500} \\times 100 = \\boxed{23.28\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 23.28% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":75,"local_id":"50075","quid":"Q1000071555","section":"MATH","topic":"Geometry","question":{"en":"Two circles with radii 12 cm and 8 cm have their centers 25 cm apart. What is the length of their transverse common tangent segment? [SSC CGL 09/10/26 Shift 2]","hi":"12 cm और 8 cm त्रिज्या वाले दो वृत्तों के केंद्र 25 cm की दूरी पर हैं। उनकी तिर्यक उभयनिष्ठ स्पर्श रेखा खंड की लंबाई क्या है? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"17 cm"},"2":{"en":"10 cm"},"3":{"en":"15 cm"},"4":{"en":"20 cm"}},"answer":"3","solution":{"en":"\\(L = \\sqrt{d^2 - (r_1 + r_2)^2}\\)<br>\\(= \\sqrt{625 - 400}\\)<br>\\(= \\boxed{15\\ \\text{cm}}\\)<br><br><b>Hence, the correct answer is option (3): 15 cm.</b>","hi":"\\(L = \\sqrt{d^2 - (r_1 + r_2)^2}\\)<br>\\(= \\sqrt{625 - 400}\\)<br>\\(= \\boxed{15\\ \\text{cm}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 15 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"ENGLISH":{"seconds":900,"questions":[{"no":76,"local_id":"50076","quid":"Q1000071556","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Choose the correct indirect speech form of the sentence given below.<br>Barbie said to me, “I want a mandolin.” [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Barbie told me that she wanted a mandolin."},"2":{"en":"Barbie told me that she wants a mandolin."},"3":{"en":"Barbie said me that she wanted a mandolin."},"4":{"en":"Barbie said to me that she has wanted a mandolin."}},"answer":"1","solution":{"en":"<b>Rule: “Said to me” becomes “told me,” and simple present becomes simple past.</b><br>“I want” becomes “she wanted.”<br>B retains present tense; C incorrectly uses “said me.”<br>D uses an unnecessary present perfect form.<br><br><b>Hence, the correct answer is option (1): Barbie told me that she wanted a mandolin..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":77,"local_id":"50077","quid":"Q1000071557","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blank with the appropriate adverb.<br>The instructions were outlined ___, leading to confusion among participants. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"minutely"},"2":{"en":"succinctly"},"3":{"en":"nebulously"},"4":{"en":"punctiliously"}},"answer":"3","solution":{"en":"<b>Nebulously (अस्पष्ट रूप से) = vaguely and unclearly.</b><br>Confusion results when instructions are outlined nebulously.<br><b>Minutely (सूक्ष्मता से)</b> = in precise detail<br><b>Succinctly (संक्षिप्त रूप से)</b> = briefly and clearly; <b>punctiliously (बारीकी से)</b> = with great attention to formal detail<br><br><b>Hence, the correct answer is option (3): nebulously.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":78,"local_id":"50078","quid":"Q1000071558","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Choose the correct direct speech transformation of the sentence below.<br>Upasana said that she hadn't seen her childhood friend for years. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Upasana said, “I haven't seen my childhood friend since previous years.”"},"2":{"en":"Upasana said, “I hadn't seen my childhood friend for years.”"},"3":{"en":"Upasana said, “I haven't seen my childhood friend for ages.”"},"4":{"en":"Upasana said, “I haven't seen my childhood friend for years.”"}},"answer":"4","solution":{"en":"<b>Rule: Past perfect in reported speech returns to present perfect in the original statement.</b><br>“She hadn’t” becomes “I haven’t,” and “her” becomes “my.”<br>A uses the unidiomatic “since previous years”; B retains past perfect.<br>C changes “for years” to “for ages,” whereas D preserves the original wording.<br><br><b>Hence, the correct answer is option (4): Upasana said, “I haven't seen my childhood friend for years.”.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":79,"local_id":"50079","quid":"Q1000071559","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Choose the correct indirect speech form of the following sentence.<br>He said, “I have never been on a submarine!” [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"He admitted that he has never been on a submarine."},"2":{"en":"He admitted that he had never been on a submarine."},"3":{"en":"He admitted that he never had been on a submarine."},"4":{"en":"He admitted that he never been on a submarine."}},"answer":"2","solution":{"en":"<b>Rule: Present perfect becomes past perfect after a past reporting verb.</b><br>“I have never been” becomes “he had never been.”<br>A fails to backshift the tense.<br>C uses unnatural auxiliary placement; D omits the auxiliary altogether.<br><br><b>Hence, the correct answer is option (2): He admitted that he had never been on a submarine..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":80,"local_id":"50080","quid":"Q1000071560","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the parts of the sentence in the correct order.<br>Amid the escalating trade war between the United States and China,<br>P. which included extensive tariffs, regulatory restrictions, and sanctions on key industries,<br>Q. disrupting global supply chains and triggering price volatility across financial markets<br>R. both nations engaged in aggressive economic retaliatory measures,<br>S. forcing multinational corporations to diversify their production hubs to mitigate risks [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"QPRS"},"2":{"en":"RSPQ"},"3":{"en":"RPQS"},"4":{"en":"PQSR"}},"answer":"3","solution":{"en":"<b>Order: RPQS</b><br>R supplies the main clause about retaliatory measures.<br>P describes those measures through “which included ….”<br>Q and S present successive consequences: disrupted supply chains, price volatility and diversified production hubs.<br><br><b>Hence, the correct answer is option (3): RPQS.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":81,"local_id":"50081","quid":"Q1000071561","section":"ENGLISH","topic":"One Word Substitution","question":{"en":"Choose the correct phrase for the word highlighted in bold.<br>The poor subordinates are made <b>scapegoats</b> by their superiors. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Blamed for others’ faults"},"2":{"en":"Given a reward for their hard work"},"3":{"en":"Promoted to a higher position"},"4":{"en":"Praised for their honesty"}},"answer":"1","solution":{"en":"<b>Scapegoat (बलि का बकरा) = a person made to bear blame for others’ mistakes.</b><br>The subordinates are unfairly blamed by their superiors.<br>Reward, promotion and praise are positive treatments and contradict the sentence.<br>The central idea is transferred blame.<br><br><b>Hence, the correct answer is option (1): Blamed for others’ faults.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":82,"local_id":"50082","quid":"Q1000071562","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Identify the error in the sentence.<br>She didn't went to the seminar last week. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"seminar"},"2":{"en":"went"},"3":{"en":"she"},"4":{"en":"last"}},"answer":"2","solution":{"en":"<b>Rule: After “didn’t,” use the base form of the verb.</b><br>“Went” is the simple past and must be replaced by “go.”<br>Correct sentence: “She didn’t <b>go</b> to the seminar last week.”<br>The other parts contain no error.<br><br><b>Hence, the correct answer is option (2): went.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":83,"local_id":"50083","quid":"Q1000071563","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the parts of the sentence in the correct order.<br>The code of digital ethics<br>P. in response to rising cyberbullying cases<br>Q. was proposed to regulate online behavior<br>R. that disrupt democratic processes<br>S. and misinformation campaigns [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"QPSR"},"2":{"en":"QPRS"},"3":{"en":"SPQR"},"4":{"en":"RPQS"}},"answer":"1","solution":{"en":"<b>Order: QPSR</b><br>Q supplies the main predicate “was proposed to regulate online behavior.”<br>P gives the reason: rising cyberbullying cases.<br>S adds misinformation campaigns, and R describes their effect on democratic processes.<br><br><b>Hence, the correct answer is option (1): QPSR.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":84,"local_id":"50084","quid":"Q1000071564","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Which of the given options arranges the following sentences in the most logical sequence to form a meaningful paragraph?<br>1. The first confirmed exoplanet was discovered in 1992, marking a breakthrough in space exploration.<br>2. In recent decades, advanced telescopes like Kepler and TESS have identified thousands of exoplanets.<br>3. Astronomers classify exoplanets based on size, atmosphere, and their position within the habitable zone.<br>4. Some exoplanets exhibit Earth-like characteristics, fueling scientific interest in their potential for hosting life.<br>5. These planets orbit stars beyond our solar system and may provide insights into the possibility of extraterrestrial life. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"2-1-3-4-5"},"2":{"en":"1-3-2-4-5"},"3":{"en":"1-5-2-3-4"},"4":{"en":"1-4-5-2-3"}},"answer":"3","solution":{"en":"<b>Order: 1-5-2-3-4</b><br>Sentence 1 introduces the first discovery, and sentence 5 explains what “these planets” are.<br>Sentence 2 moves to recent discoveries; sentence 3 explains classification.<br>Sentence 4 concludes with Earth-like examples and the possibility of life.<br><br><b>Hence, the correct answer is option (3): 1-5-2-3-4.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":85,"local_id":"50085","quid":"Q1000071565","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Which of the given options arranges the following sentences in the most logical sequence to form a meaningful paragraph?<br>1. Groups like the Society of Revolutionary Republican Women demanded equal rights and representation.<br>2. Despite their contributions, women’s rights were largely ignored in post-revolutionary France.<br>3. Women played a significant role in the French Revolution, advocating for political rights and social reforms.<br>4. This struggle laid the foundation for later feminist movements in Europe. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"4-3-2-1"},"2":{"en":"2-4-3-1"},"3":{"en":"1-4-3-2"},"4":{"en":"3-1-2-4"}},"answer":"4","solution":{"en":"<b>Order: 3-1-2-4</b><br>Sentence 3 introduces women’s role in the French Revolution.<br>Sentence 1 gives a specific group and its demands; sentence 2 contrasts contributions with subsequent neglect.<br>Sentence 4 concludes with the long-term legacy of “this struggle.”<br><br><b>Hence, the correct answer is option (4): 3-1-2-4.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":86,"local_id":"50086","quid":"Q1000071566","section":"ENGLISH","topic":"Synonym","question":{"en":"Select the most appropriate synonym of the given word: <b>ANATHEMA</b> [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Approval"},"2":{"en":"Admiration"},"3":{"en":"Curse"},"4":{"en":"Blessing"}},"answer":"3","solution":{"en":"<b>Anathema (अभिशाप) = a formal curse or something intensely detested.</b><br><b>Approval (स्वीकृति)</b> = acceptance or agreement<br><b>Admiration (प्रशंसा)</b> = respect and warm approval<br><b>Curse (अभिशाप)</b> = an invocation of harm or punishment ✔<br><b>Blessing (आशीर्वाद)</b> = a beneficial or approving prayer<br>More synonyms: malediction, execration, imprecation.<br><br><b>Hence, the correct answer is option (3): Curse.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":87,"local_id":"50087","quid":"Q1000071567","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Choose the correct meaning of idiom:<br>To ride the high horse [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"Detached and reclusive"},"2":{"en":"Arrogant and self-righteous"},"3":{"en":"Humble and grounded"},"4":{"en":"Boastful but harmless"}},"answer":"2","solution":{"en":"<b>Ride the high horse (घमंड और आत्म-सम्मान दिखाना)</b><br>It means behave arrogantly or adopt a morally superior attitude.<br>Example: “Stop riding the high horse and listen to others.”<br>Reclusiveness is unrelated; humility is the opposite.<br>The idiom does not include the qualification “but harmless.”<br><br><b>Hence, the correct answer is option (2): Arrogant and self-righteous.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":88,"local_id":"50088","quid":"Q1000071568","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the given passage, some words have been deleted. Read the passage intently and choose the most appropriate option to fill in each blank:<br><br>Urbanity, once emblematic of civic vitality and democratic congregation, has been increasingly reframed as a matrix of commodified experiences. The aesthetic uniformity of gentrified spaces, lauded for efficiency, often (1)___ the organic disorder essential to pluralistic expression. Where public squares once served as theaters of dissent, we now find algorithmically curated silence—noise filtered, identities streamlined. Technocratic governance, under the guise of neutrality, embeds surveillance into the mundane. Benches are subtly shortened to deter loitering, foliage is pruned not for shade but for visibility, and cameras peer from minimalist lampposts. These are not incidental choices but deliberate gestures in a choreography of control, wherein the citizen is (2)___ into passive compliance. Paradoxically, connectivity multiplies isolation. Inhabitants become nodes in a network, visible yet unheard, quantified but unrepresented. The language of “smart” infrastructure conceals a deeper estrangement—between place and person, inhabitant and city. Without contestation, the commons may be transmuted into a theatre of managed appearance, and freedom reduced to (3)___ within programmed boundaries. What masquerades as urban renewal might, in truth, be an erasure—a calculated (4)___ of messiness, unpredictability, and resistance. In this theatre of optimization, dissent must either be re-scripted or (5)___.<br><br><br>What should come in the place of blank number [1]? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"masks"},"2":{"en":"heightens"},"3":{"en":"reclaims"},"4":{"en":"energizes"}},"answer":"1","solution":{"en":"<b>Masks (छिपाता है) = conceals or covers.</b><br>Aesthetic uniformity hides the organic disorder needed for pluralistic expression.<br><b>Heightens (बढ़ाता है)</b> = intensifies<br><b>Reclaims (पुनः प्राप्त करता है)</b> = retrieves; <b>energizes (सजीव करता है)</b> = gives energy<br><br><b>Hence, the correct answer is option (1): masks.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":89,"local_id":"50089","quid":"Q1000071569","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the given passage, some words have been deleted. Read the passage intently and choose the most appropriate option to fill in each blank:<br><br>Urbanity, once emblematic of civic vitality and democratic congregation, has been increasingly reframed as a matrix of commodified experiences. The aesthetic uniformity of gentrified spaces, lauded for efficiency, often (1)___ the organic disorder essential to pluralistic expression. Where public squares once served as theaters of dissent, we now find algorithmically curated silence—noise filtered, identities streamlined. Technocratic governance, under the guise of neutrality, embeds surveillance into the mundane. Benches are subtly shortened to deter loitering, foliage is pruned not for shade but for visibility, and cameras peer from minimalist lampposts. These are not incidental choices but deliberate gestures in a choreography of control, wherein the citizen is (2)___ into passive compliance. Paradoxically, connectivity multiplies isolation. Inhabitants become nodes in a network, visible yet unheard, quantified but unrepresented. The language of “smart” infrastructure conceals a deeper estrangement—between place and person, inhabitant and city. Without contestation, the commons may be transmuted into a theatre of managed appearance, and freedom reduced to (3)___ within programmed boundaries. What masquerades as urban renewal might, in truth, be an erasure—a calculated (4)___ of messiness, unpredictability, and resistance. In this theatre of optimization, dissent must either be re-scripted or (5)___.<br><br><br>What should come in the place of blank number [2]? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"galvanized"},"2":{"en":"domesticated"},"3":{"en":"inducted"},"4":{"en":"stimulated"}},"answer":"2","solution":{"en":"<b>Domesticated (वश में किया गया) = made tame, controlled or compliant.</b><br>It fits the metaphor of citizens being trained into passive obedience.<br><b>Galvanized (प्रेरित)</b> = shocked into action<br><b>Inducted (भर्ती किया गया)</b> = formally admitted; <b>stimulated (उत्तेजित)</b> = encouraged into activity<br><br><b>Hence, the correct answer is option (2): domesticated.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":90,"local_id":"50090","quid":"Q1000071570","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the given passage, some words have been deleted. Read the passage intently and choose the most appropriate option to fill in each blank:<br><br>Urbanity, once emblematic of civic vitality and democratic congregation, has been increasingly reframed as a matrix of commodified experiences. The aesthetic uniformity of gentrified spaces, lauded for efficiency, often (1)___ the organic disorder essential to pluralistic expression. Where public squares once served as theaters of dissent, we now find algorithmically curated silence—noise filtered, identities streamlined. Technocratic governance, under the guise of neutrality, embeds surveillance into the mundane. Benches are subtly shortened to deter loitering, foliage is pruned not for shade but for visibility, and cameras peer from minimalist lampposts. These are not incidental choices but deliberate gestures in a choreography of control, wherein the citizen is (2)___ into passive compliance. Paradoxically, connectivity multiplies isolation. Inhabitants become nodes in a network, visible yet unheard, quantified but unrepresented. The language of “smart” infrastructure conceals a deeper estrangement—between place and person, inhabitant and city. Without contestation, the commons may be transmuted into a theatre of managed appearance, and freedom reduced to (3)___ within programmed boundaries. What masquerades as urban renewal might, in truth, be an erasure—a calculated (4)___ of messiness, unpredictability, and resistance. In this theatre of optimization, dissent must either be re-scripted or (5)___.<br><br><br>What should come in the place of blank number [3]? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"iteration"},"2":{"en":"containment"},"3":{"en":"freedom"},"4":{"en":"circulation"}},"answer":"2","solution":{"en":"<b>Containment (सीमाबद्धता) = restriction within limits.</b><br>Freedom is reduced to containment within programmed boundaries.<br><b>Iteration (पुनरावृत्ति)</b> = repetition<br><b>Freedom (स्वतंत्रता)</b> repeats the original noun illogically; <b>circulation (संचरण)</b> = movement or distribution<br><br><b>Hence, the correct answer is option (2): containment.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":91,"local_id":"50091","quid":"Q1000071571","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the given passage, some words have been deleted. Read the passage intently and choose the most appropriate option to fill in each blank:<br><br>Urbanity, once emblematic of civic vitality and democratic congregation, has been increasingly reframed as a matrix of commodified experiences. The aesthetic uniformity of gentrified spaces, lauded for efficiency, often (1)___ the organic disorder essential to pluralistic expression. Where public squares once served as theaters of dissent, we now find algorithmically curated silence—noise filtered, identities streamlined. Technocratic governance, under the guise of neutrality, embeds surveillance into the mundane. Benches are subtly shortened to deter loitering, foliage is pruned not for shade but for visibility, and cameras peer from minimalist lampposts. These are not incidental choices but deliberate gestures in a choreography of control, wherein the citizen is (2)___ into passive compliance. Paradoxically, connectivity multiplies isolation. Inhabitants become nodes in a network, visible yet unheard, quantified but unrepresented. The language of “smart” infrastructure conceals a deeper estrangement—between place and person, inhabitant and city. Without contestation, the commons may be transmuted into a theatre of managed appearance, and freedom reduced to (3)___ within programmed boundaries. What masquerades as urban renewal might, in truth, be an erasure—a calculated (4)___ of messiness, unpredictability, and resistance. In this theatre of optimization, dissent must either be re-scripted or (5)___.<br><br><br>What should come in the place of blank number [4]? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"celebration"},"2":{"en":"aggression"},"3":{"en":"purification"},"4":{"en":"exile"}},"answer":"3","solution":{"en":"<b>Purification (शुद्धिकरण) = removal of unwanted elements.</b><br>Urban renewal is portrayed as removing messiness, unpredictability and resistance.<br><b>Celebration (उत्सव)</b> is contrary to “erasure.”<br><b>Aggression (आक्रमण)</b> = hostility; <b>exile (निर्वासन)</b> = expulsion of a person, not these abstract qualities<br><br><b>Hence, the correct answer is option (3): purification.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":92,"local_id":"50092","quid":"Q1000071572","section":"ENGLISH","topic":"Cloze Test","question":{"en":"In the given passage, some words have been deleted. Read the passage intently and choose the most appropriate option to fill in each blank:<br><br>Urbanity, once emblematic of civic vitality and democratic congregation, has been increasingly reframed as a matrix of commodified experiences. The aesthetic uniformity of gentrified spaces, lauded for efficiency, often (1)___ the organic disorder essential to pluralistic expression. Where public squares once served as theaters of dissent, we now find algorithmically curated silence—noise filtered, identities streamlined. Technocratic governance, under the guise of neutrality, embeds surveillance into the mundane. Benches are subtly shortened to deter loitering, foliage is pruned not for shade but for visibility, and cameras peer from minimalist lampposts. These are not incidental choices but deliberate gestures in a choreography of control, wherein the citizen is (2)___ into passive compliance. Paradoxically, connectivity multiplies isolation. Inhabitants become nodes in a network, visible yet unheard, quantified but unrepresented. The language of “smart” infrastructure conceals a deeper estrangement—between place and person, inhabitant and city. Without contestation, the commons may be transmuted into a theatre of managed appearance, and freedom reduced to (3)___ within programmed boundaries. What masquerades as urban renewal might, in truth, be an erasure—a calculated (4)___ of messiness, unpredictability, and resistance. In this theatre of optimization, dissent must either be re-scripted or (5)___.<br><br><br>What should come in the place of blank number [5]? [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"expunged"},"2":{"en":"dramatized"},"3":{"en":"validated"},"4":{"en":"softened"}},"answer":"1","solution":{"en":"<b>Expunged (मिटा दिया गया) = erased or removed completely.</b><br>Dissent must either be rewritten or eliminated under total optimization.<br><b>Dramatized (नाटकीय बनाया)</b> = presented dramatically<br><b>Validated (मान्य किया)</b> = approved; <b>softened (कोमल किया)</b> = made less severe<br><br><b>Hence, the correct answer is option (1): expunged.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":93,"local_id":"50093","quid":"Q1000071573","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blank with the correct preposition:<br>The decision was made ___ consultation with the stakeholders. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"by"},"2":{"en":"under"},"3":{"en":"upon"},"4":{"en":"in"}},"answer":"4","solution":{"en":"<b>Rule: “In consultation with” is the fixed phrase meaning after discussing with someone.</b><br>Correct sentence: “The decision was made <b>in</b> consultation with the stakeholders.”<br>“By,” “under” and “upon” do not form this standard collocation.<br>The phrase indicates stakeholder participation in the decision.<br><br><b>Hence, the correct answer is option (4): in.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":94,"local_id":"50094","quid":"Q1000071574","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Find the part of the sentence that contains an error:<br>The correlation-matrix visualization (1)/ appeared more clear (2)/ when the superfluous variables were removed (3)/ during the second iteration of analysis. (4)/ [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"(1)"},"2":{"en":"(2)"},"3":{"en":"(3)"},"4":{"en":"(4)"}},"answer":"2","solution":{"en":"<b>Rule: The comparative of “clear” is “clearer.”</b><br>Part (2) should read “appeared <b>clearer</b>,” not “more clear.”<br>The comparison concerns the visualization before and after variables were removed.<br>The other parts are correct.<br><br><b>Hence, the correct answer is option (2): (2).</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":95,"local_id":"50095","quid":"Q1000071575","section":"ENGLISH","topic":"Active Passive Voice","question":{"en":"Change the following from active to passive:<br>The chef was preparing the dessert when we arrived. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"The dessert is being prepared by the chef when we arrived."},"2":{"en":"The dessert was being prepared by the chef when we arrived."},"3":{"en":"The dessert has been prepared by the chef."},"4":{"en":"The dessert had been prepared by the chef when we arrived."}},"answer":"2","solution":{"en":"<b>Rule: Past continuous passive = was/were being + past participle.</b><br>The singular object “the dessert” becomes the subject and takes “was being.”<br>Correct form: “The dessert <b>was being prepared</b> by the chef when we arrived.”<br>A changes to present continuous; C omits ongoing action; D changes to past perfect.<br><br><b>Hence, the correct answer is option (2): The dessert was being prepared by the chef when we arrived..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":96,"local_id":"50096","quid":"Q1000071576","section":"ENGLISH","topic":"Active Passive Voice","question":{"en":"Change the following from active to passive:<br>Someone is following us. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"We are being followed."},"2":{"en":"We are followed."},"3":{"en":"We have been followed."},"4":{"en":"We were being followed."}},"answer":"1","solution":{"en":"<b>Rule: Present continuous passive = am/is/are being + past participle.</b><br>“Us” becomes “we,” and the unspecified agent need not be repeated.<br>Correct form: “We <b>are being followed</b>.”<br>B uses simple present, C present perfect, and D past continuous.<br><br><b>Hence, the correct answer is option (1): We are being followed..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":97,"local_id":"50097","quid":"Q1000071577","section":"ENGLISH","topic":"Active Passive Voice","question":{"en":"Convert the sentence provided below from its passive voice structure to an active voice structure:<br>The committee was believed to have been working on a draft since January. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"It is believed that the committee was working on a draft since January."},"2":{"en":"Someone believed the draft worked itself since January."},"3":{"en":"It is believed that a draft was written on the committee."},"4":{"en":"The committee had believed the draft was working."}},"answer":"1","solution":{"en":"<b>Rule: Recast the infinitive as a finite clause while retaining the original meaning.</b><br>Option A preserves the belief that the committee had been working on a draft since January.<br>B illogically says the draft worked itself; C changes the committee into a surface on which a draft was written.<br>D assigns the belief to the committee and makes the draft the working agent.<br><br><b>Hence, the correct answer is option (1): It is believed that the committee was working on a draft since January..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":98,"local_id":"50098","quid":"Q1000071578","section":"ENGLISH","topic":"Active Passive Voice","question":{"en":"Convert the sentence provided below from its passive voice structure to an active voice structure:<br>It was concluded that the suspects had been hiding in plain sight. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"The suspects were concluded to hide in plain sight."},"2":{"en":"Someone concluded the suspects were hiding in plain sight."},"3":{"en":"It was concluded that the suspects were hiding in plain sight."},"4":{"en":"The conclusion was hiding of the suspects."}},"answer":"3","solution":{"en":"<b>Rule: Retain the impersonal conclusion and the idiom “in plain sight.”</b><br>Option C preserves the conclusion and the suspects’ continuous concealment.<br>A uses the unidiomatic “were concluded to hide.”<br>B changes “in plain sight” to “plainly,” altering the meaning; D is ungrammatical.<br><br><b>Hence, the correct answer is option (3): It was concluded that the suspects were hiding in plain sight..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":99,"local_id":"50099","quid":"Q1000071579","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the most suitable option to replace the highlighted part of the sentence:<br>The teacher <b>explained us</b> the lesson clearly. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"explained the lesson to us"},"2":{"en":"explained to us the lesson"},"3":{"en":"had explained us"},"4":{"en":"explained we the lesson"}},"answer":"1","solution":{"en":"<b>Rule: “Explain something to somebody” is the standard construction.</b><br>Correct sentence: “The teacher <b>explained the lesson to us</b> clearly.”<br>B is grammatically possible but unnecessarily awkward; C changes the tense and omits “to.”<br>D incorrectly uses the subject pronoun “we” as an object.<br><br><b>Hence, the correct answer is option (1): explained the lesson to us.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":100,"local_id":"50100","quid":"Q1000071580","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"A sentence is provided in indirect speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding direct speech.<br>The journalist said that under no condition would the authorities release the documents early. [SSC CGL 09/10/26 Shift 2]"},"options":{"1":{"en":"“Under no condition will the authorities release the documents early,” said the journalist."},"2":{"en":"“Authorities will not release the documents early under any condition,” he said."},"3":{"en":"“Under no condition would the authorities release the documents early,” said the journalist."},"4":{"en":"“The documents shall not be released early,” said the journalist."}},"answer":"3","solution":{"en":"<b>Rule: Restore quotation marks while retaining the emphatic negative opening and inversion.</b><br>“Under no condition would the authorities …” exactly matches the reported wording and modal force.<br>A changes “would” to “will”; B removes inversion and changes the reporting subject.<br>D changes to passive voice and replaces the modal with “shall.”<br><br><b>Hence, the correct answer is option (3): “Under no condition would the authorities release the documents early,” said the journalist..</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]}}};